/* ==========================================================================
   i18n.js — the app in Arabic or English.
   Every piece of Arabic text in the code goes through tx('…'): in English it is
   looked up in LANG_EN (lang-en.js, made by tools/lang_en.py). txe('ع', 'E') is
   for the few short pieces whose English depends on where they are used.
   The language is chosen in Settings and applies after the app restarts.
   A first start follows the device's language; an app that was already in use
   stays in Arabic until the viewer changes it.
   ========================================================================== */
var I18N = (function () {
  var KEY = 'iptv.lang';
  var lang = '';
  try { lang = localStorage.getItem(KEY) || ''; } catch (e) {}
  if (!lang) { try { lang = (JSON.parse(localStorage.getItem('iptv.settings') || '{}') || {}).lang || ''; } catch (e) {} }
  if (lang !== 'ar' && lang !== 'en') {
    var used = false;
    try { used = !!(localStorage.getItem('iptv.settings') || localStorage.getItem('iptv.account') || localStorage.getItem('iptv.playlists')); } catch (e) {}
    var nav = String((navigator.languages && navigator.languages[0]) || navigator.language || '').toLowerCase();
    lang = used || !nav || nav.indexOf('ar') === 0 ? 'ar' : 'en';
  }
  var en = lang === 'en';
  var root = document.documentElement;
  root.setAttribute('lang', lang);
  root.setAttribute('dir', en ? 'ltr' : 'rtl');
  if (en) root.className += ' lang-en';

  function t(s) {
    if (!en || s === undefined || s === null) return s;
    var v = window.LANG_EN && LANG_EN[s];
    return v === undefined ? s : v;
  }
  /* the fixed text of the page itself (index.html): its words and labels */
  var ATTRS = ['aria-label', 'placeholder', 'title'];
  var AR = /[؀-ۿ]/;
  function page(el) {
    if (!en || !el) return;
    var walk = document.createTreeWalker(el, 4, null, false), n, list = [];
    while ((n = walk.nextNode())) list.push(n);
    for (var i = 0; i < list.length; i++) {
      var v = list[i].nodeValue, k = v.replace(/^\s+|\s+$/g, '');
      if (k && AR.test(k)) { var e = t(k); if (e !== k) list[i].nodeValue = v.replace(k, e); }
    }
    var all = el.querySelectorAll('[aria-label],[placeholder],[title]');
    for (var j = 0; j < all.length; j++) {
      for (var a = 0; a < ATTRS.length; a++) {
