    }
  }
  function set(l) {
    try { localStorage.setItem(KEY, l === 'en' ? 'en' : 'ar'); } catch (e) {}
    try { if (window.Store) Store.setSetting('lang', l === 'en' ? 'en' : 'ar'); } catch (e) {}
  }
