  var forced = (/[?&]dev=(phone|tablet|tv|remote)/.exec(location.search) || [])[1] || '';
  /* LG and Android TV (Sony ...): the new screens, driven by the remote */
  var remote = forced === 'remote' || (!forced && (!!window.WEBOS_APP || !!(window.ANDROID_APP && window.IS_TV)));
  var kind = 'tv', size = '', land = true;

  function detect() {
    if (remote) return 'touch';
    if (forced) return forced === 'tv' ? 'tv' : 'touch';
    if (window.IS_TV || window.WEBOS_APP) return 'tv';
    if (window.ANDROID_APP) return 'touch';
    if (window.MAC_APP) return 'touch';                   /* the Mac app: the same screens, used with a mouse */
    if (window.tizen) return 'tv';                        /* Samsung TV */
    return ('ontouchstart' in window) ? 'touch' : 'tv';   /* a browser: a PC acts like a TV */
  }

  function measure() {
    var w = window.innerWidth || 1, h = window.innerHeight || 1;
    land = w >= h;
