    if (forced === 'phone') size = 'phone';
    else if (forced === 'tablet' || remote || window.MAC_APP) size = 'tablet';   /* a Mac window, however small, keeps the big screens */
    else size = (lo < 600 && hi < 1000) ? 'phone' : 'tablet';
