  return {
    touch: function () { return kind === 'touch'; },
    tv: function () { return kind === 'tv'; },
    remote: function () { return remote; },
    size: function () { return size; },
    phone: function () { return size === 'phone'; },
    landscape: function () { return land; },
    onChange: null,
    /* the video turns the phone sideways; the rest of the app follows the phone */
    orientation: function (mode) {
