/* --------------------------------------------------------------------------
   Remote-control keys. Converts key codes to simple names.
   Desktop keyboard equivalents are included so the app can be tested on a PC.
   -------------------------------------------------------------------------- */
var Keys = (function () {
  var MAP = {
    37: 'left', 38: 'up', 39: 'right', 40: 'down', 13: 'enter',
    10009: 'back', 27: 'back',
    415: 'play', 19: 'pause', 10252: 'playpause', 32: 'playpause',
    413: 'stop', 417: 'ff', 412: 'rw',
    427: 'chup', 428: 'chdown', 33: 'chup', 34: 'chdown',
    403: 'red', 404: 'green', 405: 'yellow', 406: 'blue',
    112: 'red', 113: 'green', 114: 'yellow', 115: 'blue',   /* F1..F4 on a PC */
    457: 'info', 73: 'info',
    10182: 'exit',
    65376: 'imedone', 65385: 'imecancel'
