    var c = e.keyCode;
    if (c >= 96 && c <= 105) return c - 96;
    return c - 48;
  }

  return { register: register, name: name, digit: digit };
})();

/* diag.js — what happened to the last films and channels played, kept ON THIS DEVICE only
   (nothing leaves it): the engine that played, how long the start took, why one failed.
   Settings → Updates → «سجل التشغيل» shows it, so a problem can be read off the screen. */
