    cover: { mode: 'cover', z: 1, name: tx('ملء الشاشة'), desc: tx('تملأ الشاشة وتقص الأطراف الزائدة') },
    fill:  { mode: 'fill', z: 1, name: tx('تمطيط'), desc: tx('تملأ الشاشة كلها وقد تتمدد الصورة') },
