    es: tx('الإسبانية'), spa: tx('الإسبانية'), de: tx('الألمانية'), ger: tx('الألمانية'), deu: tx('الألمانية'),
    it: tx('الإيطالية'), ita: tx('الإيطالية'), hi: tx('الهندية'), hin: tx('الهندية'), ur: tx('الأردية'), urd: tx('الأردية'),
    fa: tx('الفارسية'), per: tx('الفارسية'), fas: tx('الفارسية'), ru: tx('الروسية'), rus: tx('الروسية'),
    ko: tx('الكورية'), kor: tx('الكورية'), ja: tx('اليابانية'), jpn: tx('اليابانية'), pt: tx('البرتغالية'), por: tx('البرتغالية')
