/* ==========================================================================
   parental.js — the parental PIN, locked categories, hidden categories and
   the user's own order of categories.
   - The PIN belongs to the device; hidden / locked / order belong to each
     playlist (stored with it in Store).
   - Entering the PIN once unlocks everything until the app is closed.
   - Hidden and locked categories also stay out of "all", search, favourites
     and "continue watching".
   ========================================================================== */
var Parental = (function () {
  var unlocked = false;

  function has() { return !!Store.getPin(); }
  function isUnlocked() { return unlocked || !has(); }
  function lock() { unlocked = false; }

  /* asks for the PIN when one is set; cb(true) when allowed */
  function ask(text, cb) {
    if (isUnlocked()) { cb(true); return; }
    (function tryIt(err) {
      UI.pin({
        title: tx('أدخل رمز الحماية'), text: text || '', error: err,
        onDone: function (v) {
          if (v === null) { cb(false); return; }
          if (v === Store.getPin()) { unlocked = true; cb(true); return; }
          tryIt(tx('الرمز غير صحيح، حاول مرة أخرى'));
        }
      });
    })('');
  }

  /* a new PIN, typed twice; cb(true) when saved */
  function create(cb) {
    UI.pin({
      title: tx('رمز حماية جديد'), text: tx('اختر 4 أرقام تتذكرها، ولا تخبر بها الأطفال'),
      onDone: function (a) {
        if (a === null) { cb(false); return; }
        UI.pin({
          title: tx('أعد كتابة الرمز'), text: tx('للتأكيد'),
          onDone: function (b) {
            if (b === null) { cb(false); return; }
            if (a !== b) { UI.toast(tx('الرمزان غير متطابقين، حاول مرة أخرى')); cb(false); return; }
            Store.setPin(a);
            unlocked = true;
            UI.toast(tx('تم حفظ رمز الحماية') + ' ✓');
            cb(true);
          }
        });
      }
    });
  }

  /* the settings row: set, change or remove the PIN */
  function menu(done) {
    if (!has()) { create(function () { if (done) done(); }); return; }
    ask(tx('لتغيير رمز الحماية أو إلغائه'), function (ok) {
      if (!ok) { if (done) done(); return; }
      UI.menu({
        title: tx('رمز حماية الأطفال'),
        items: [
          { label: tx('تغيير الرمز'), value: 'change' },
          { label: tx('إلغاء الرمز'), sub: tx('تُفتح كل الأقسام المقفولة'), value: 'off' }
        ],
        onSelect: function (v) {
          if (v === 'change') { create(function () { if (done) done(); }); return; }
          if (v === 'off') { Store.setPin(''); unlocked = false; UI.toast(tx('تم إلغاء رمز الحماية')); }
          if (done) done();
        }
      });
    });
  }

  /* ---------- categories ---------- */
  function prefs(type) { return Store.getCatPrefs(type); }

  /* the server's categories as the user arranged them: hidden ones left out,
     the user's order first (new categories after it), locked ones marked */
  function arrange(type, cats) {
    var p = prefs(type), pos = {}, out = [], i;
    for (i = 0; i < p.order.length; i++) pos[p.order[i]] = i;
    for (i = 0; i < cats.length; i++) {
      var c = cats[i], id = String(c.id);
      if (p.hidden[id]) continue;
      out.push({ id: c.id, name: c.name, locked: !!p.locked[id], n: i });
    }
    out.sort(function (a, b) {
      var pa = pos.hasOwnProperty(String(a.id)) ? pos[String(a.id)] : 1e6 + a.n;
      var pb = pos.hasOwnProperty(String(b.id)) ? pos[String(b.id)] : 1e6 + b.n;
      return pa - pb;
    });
    return out;
  }

  /* categories whose items stay out of the lists right now */
  function blocked(type) {
    var p = prefs(type), out = {}, any = false, k;
    for (k in p.hidden) if (p.hidden.hasOwnProperty(k)) { out[k] = true; any = true; }
    if (!isUnlocked()) for (k in p.locked) if (p.locked.hasOwnProperty(k)) { out[k] = true; any = true; }
    return any ? out : null;
  }

  function filter(type, items) {
    var b = blocked(type);
    if (!b || !items) return items;
    var out = [];
    for (var i = 0; i < items.length; i++) if (!b[String(items[i].cat)]) out.push(items[i]);
    return out;
  }

  function setHidden(type, cat, on) {
    var p = prefs(type), id = String(cat.id);
    if (on) p.hidden[id] = cat.name; else delete p.hidden[id];
    Store.setCatPrefs(type, p);
  }
  function setLocked(type, cat, on) {
    var p = prefs(type), id = String(cat.id);
    if (on) p.locked[id] = cat.name; else delete p.locked[id];
    Store.setCatPrefs(type, p);
  }
  function setOrder(type, ids) {
    var p = prefs(type);
    p.order = ids;
    Store.setCatPrefs(type, p);
  }

  /* every hidden category of the playlist in use: [{type, id, name}] */
  function hiddenList() {
    var out = [], T = ['live', 'vod', 'series'];
    for (var t = 0; t < T.length; t++) {
      var h = prefs(T[t]).hidden;
      for (var k in h) if (h.hasOwnProperty(k)) out.push({ type: T[t], id: k, name: h[k] });
    }
    return out;
  }

  var TYPE_NAME = { live: tx('مباشر'), vod: tx('أفلام'), series: tx('مسلسلات') };

  /* the settings row: bring hidden categories back */
  function hiddenMenu(done) {
    var list = hiddenList();
    if (!list.length) { UI.toast(tx('لا توجد أقسام مخفية')); if (done) done(); return; }
    ask(tx('لإظهار الأقسام المخفية'), function (ok) {
      if (!ok) { if (done) done(); return; }
      var items = [{ label: tx('إظهار كل الأقسام'), value: '*' }];
      for (var i = 0; i < list.length; i++) items.push({ label: list[i].name, sub: TYPE_NAME[list[i].type], value: i });
      UI.menu({
        title: tx('الأقسام المخفية'), items: items, hint: tx('اختر قسماً لإظهاره'),
        onSelect: function (v) {
          if (v === '*') {
            for (var j = 0; j < list.length; j++) setHidden(list[j].type, list[j], false);
            UI.toast(tx('ظهرت كل الأقسام'));
          } else if (v !== null && list[v]) {
            setHidden(list[v].type, list[v], false);
            UI.toast(tx('ظهر قسم') + ' «' + list[v].name + '»');
          }
          if (done) done();
        }
      });
    });
  }

  return {
    has: has, isUnlocked: isUnlocked, lock: lock, ask: ask, create: create, menu: menu,
    arrange: arrange, filter: filter, blocked: blocked,
    setHidden: setHidden, setLocked: setLocked, setOrder: setOrder,
    hiddenList: hiddenList, hiddenMenu: hiddenMenu
  };
})();

