    bestIx[type] = ix;
    return ix;
  }
  function top(type, cb) {
    var acct = Store.acctKey();
    Xtream.getStreams(type, null, function (err, all) {
      if (err || !all) return cb(err || { code: 'empty' }, []);
      var list = Parental.filter(type, all), c = topCache[type];
      if (c && c.acct === acct && c.src === all && c.n === list.length) return cb(null, c.out);
      if (!window.Best) return cb(null, []);
      var ix = bestIndex(type), found = [], i;
      for (i = 0; i < list.length; i++) {
        var it = list[i], cand = ix[bestKey(it.name)];
        if (!cand) continue;
        for (var k = 0; k < cand.length; k++) {
          var e = cand[k];
          if (it.year && Math.abs(it.year - e.y) > 1) continue;
          var prev = found[e.rank];
          if (!prev || (!prev.it.icon && it.icon)) found[e.rank] = { it: it, osc: e.osc };
          break;
        }
      }
      var out = [], osc = {};
      for (i = 0; i < found.length && out.length < TOP_MAX; i++) {
        if (!found[i]) continue;
        out.push(found[i].it);
        if (found[i].osc) osc[found[i].it.id] = true;
      }
      oscarIds[type] = osc;
      topCache[type] = { acct: acct, src: all, n: list.length, out: out };
      cb(null, out);
    });
  }
  function isOscar(it) { return !!(it && oscarIds[it.type] && oscarIds[it.type][it.id]); }

  /* ---------------- words for the screens ---------------- */
  function partsText(n) {
    if (window.I18N && I18N.en) return n === 1 ? '1 part' : n + ' parts';
    if (n === 1) return 'جزء واحد';
    if (n === 2) return 'جزءان';
    return n + (n <= 10 ? ' أجزاء' : ' جزءاً');
  }
  function yearsText(s) { return !s.from ? '' : (s.from === s.to ? String(s.from) : s.from + ' – ' + s.to); }
  function partName(s, i) {
    var n = (s && s.nums && s.nums[i]) || i + 1;
    if (window.I18N && I18N.en) return 'Part ' + n;
    return 'الجزء ' + (n <= 10 ? ORD_NAME[n - 1] : String(n));
  }
  /* does the series answer what was typed (its names, or the titles it looks for) */
  function find(q, cb) {
    q = clean(q);
    if (!q) return cb([]);
    get(function (err, list) {
      if (err || !list) return cb([]);
      var hits = [];
      for (var s = 0; s < list.length; s++) {
        var L = null;
        for (var g = 0; g < LIST.length; g++) if (LIST[g].id === list[s].id) L = LIST[g];
        var words = [L.n, L.en].concat(L.k || [], L.s || [], L.e || []);
        for (var w = 0; w < words.length; w++) {
          if ((' ' + clean(words[w])).indexOf(' ' + q) !== -1) { hits.push(list[s]); break; }
        }
      }
      cb(hits);
    });
  }

  return { get: get, byId: byId, ofItem: ofItem, top: top, find: find, partsText: partsText, yearsText: yearsText, partName: partName, isOscar: isOscar,
    /* for tests */ _core: core, _compute: compute, _clean: clean };
})();

/* ==========================================================================
   Login screen — server, username, password  +  "login from phone" QR code
   ========================================================================== */
Screens.login = {
  f: 0,                 /* focused row: -2 the kind (Xtream / M3U), -1 name, 0 server, 1 user, 2 pass, 3 button */
  eye: false,           /* the remote is on the show-password button beside the password */
  params: {},
  busy: false,
  mode: 'xtream',       /* 'm3u': row 0 is the list link, row 1 its guide link, no row 2 */

  STATUS: {
    connecting: tx('جاري تجهيز الرمز...'),
    ready: tx('في انتظار الجوال...'),
    offline: tx('خدمة الربط غير متاحة حالياً، استخدم الريموت'),
    received: tx('تم استلام البيانات من الجوال') + ' ✓'
  },

  inputs: function () { return [U.$('lg-server'), U.$('lg-user'), U.$('lg-pass')]; },

  show: function (params) {
    this.params = params || {};
    var acc = this.params.preset || (this.params.add ? {} : (Store.getAccount() || {}));
    var ins = this.inputs();
    U.$('lg-name').value = (this.params.preset && this.params.preset.name) || '';
    this.showPass(false);
    U.$('lg-btn').innerHTML = this.params.preset ? tx('حفظ') : this.params.add ? tx('إضافة القائمة') : tx('تسجيل الدخول');
    var m3u = acc.kind === 'm3u';
    ins[0].value = (m3u ? acc.url : acc.server) || '';
    ins[1].value = (m3u ? acc.epg : acc.username) || '';
    ins[2].value = (m3u ? '' : acc.password) || '';
    this.setMode(m3u ? 'm3u' : 'xtream');
    this.f = ins[0].value ? 3 : 0;
    this.busy = false;
    this.msg(this.params.message || '');
    this.draw();
    this.startPairing();
  },

  hide: function () {
    var ins = this.inputs();
    for (var i = 0; i < 3; i++) ins[i].blur();
    U.$('lg-name').blur();
    Pair.stop();
  },

  /* the password in plain sight or hidden */
  showPass: function (on) {
    var p = U.$('lg-pass'), e = U.$('lg-eye');
    if (!p) return;
    p.type = on ? 'text' : 'password';
    if (e) { U.toggleClass(e, 'on', !!on); e.setAttribute('aria-label', on ? tx('إخفاء كلمة المرور') : tx('إظهار كلمة المرور')); }
  },
  togglePass: function () { var p = U.$('lg-pass'); this.showPass(p && p.type === 'password'); },

  visibility: function (hidden) {
    if (hidden) Pair.stop();
    else this.startPairing();
  },

  /* ---------------- phone pairing ---------------- */
  startPairing: function () {
    var self = this;
    var card = U.$('qr-card');
    if (!Pair.enabled()) { card.style.display = 'none'; return; }
    card.style.display = '';
    var s = Pair.start({
      onStatus: function (st) { self.pairStatus(st); },
      onCredentials: function (c) { self.fromPhone(c); }
    });
    try {
      QR.drawCanvas(U.$('qr-canvas'), s.url, { ecl: 'M', px: 300, margin: 3 });
    } catch (e) {
      card.style.display = 'none';
    }
  },

  pairStatus: function (st) {
    var el = U.$('qr-status');
    el.className = 'qr-status ' + st;
    el.querySelector('span').innerHTML = U.esc(this.STATUS[st] || '');
  },

  fromPhone: function (c) {
    var ins = this.inputs();
    for (var i = 0; i < 3; i++) ins[i].blur();
    if (c.kind === 'm3u' || (!c.username && Xtream.m3uLink(c.url || c.server))) {
      ins[0].value = c.url || c.server;
      ins[1].value = c.epg || '';
      ins[2].value = '';
      this.setMode('m3u');
      this.f = 3;
      this.draw();
      UI.toast(tx('تم استلام رابط القائمة من الجوال'));
      this.submit();
      return;
    }
    this.setMode('xtream');
    var p = Xtream.parseServer(c.server);
    ins[0].value = p.server || c.server;
    ins[1].value = c.username;
    ins[2].value = c.password;
    this.f = 3;
    this.draw();
    UI.toast(tx('تم استلام بيانات الحساب من الجوال'));
    this.submit();
  },

  /* ---------------- form ---------------- */
  msg: function (t) { U.$('lg-msg').innerHTML = U.esc(t); },

  /* an M3U link: the second row asks for its programme guide, the third is hidden */
  setMode: function (m) {
    this.mode = m;
    var tabs = this.el.querySelectorAll('.lg-tab');
    for (var t = 0; t < tabs.length; t++) U.toggleClass(tabs[t], 'on', tabs[t].getAttribute('data-mode') === m);
    var server = U.$('lg-server'), user = U.$('lg-user'), pass = U.$('lg-pass');
    var lab = [server.parentNode.querySelector('label'), user.parentNode.querySelector('label')];
    lab[0].innerHTML = m === 'm3u' ? tx('رابط قائمة') + ' M3U' : tx('رابط السيرفر');
    lab[1].innerHTML = m === 'm3u' ? tx('رابط دليل البرامج XMLTV (اختياري)') : tx('اسم المستخدم');
    server.setAttribute('placeholder', m === 'm3u' ? 'http://example.com/get.php?…' : 'http://example.com:8080');
    pass.parentNode.parentNode.style.display = m === 'm3u' ? 'none' : '';
  },

  draw: function () {
    var rows = this.el.querySelectorAll('[data-f]');
    for (var i = 0; i < rows.length; i++) {
      U.toggleClass(rows[i], 'focused', parseInt(rows[i].getAttribute('data-f'), 10) === this.f && !(this.eye && this.f === 2));
    }
    U.toggleClass(U.$('lg-eye'), 'focused', this.eye && this.f === 2);
    /* the chosen row stays in sight on a short screen */
    var fr = this.el.querySelector('[data-f].focused') || U.$('lg-eye');
    if (fr && window.Device && Device.touch()) { try { if (fr.scrollIntoViewIfNeeded) fr.scrollIntoViewIfNeeded(false); } catch (e) {} }
  },

  input: function (f) { return f === -1 ? U.$('lg-name') : this.inputs()[f]; },

  edit: function () {
    if (this.f === -2) { this.setMode(this.mode === 'm3u' ? 'xtream' : 'm3u'); return; }
    if (this.f === 2 && this.eye) { this.togglePass(); return; }
    var inp = this.input(this.f);
    if (!inp) return;
    inp.focus();
    try { inp.setSelectionRange(inp.value.length, inp.value.length); } catch (e) {}
  },

  /* after typing the server: if it was a full M3U link, take user/pass from it */
  afterServer: function () {
    var ins = this.inputs();
    var p = Xtream.parseServer(ins[0].value);
    if (!p.username && Xtream.m3uLink(ins[0].value) && (this.mode === 'm3u' || (!ins[1].value && !ins[2].value))) {
      if (this.mode !== 'm3u') { ins[1].value = ''; UI.toast(tx('رابط قائمة M3U — أضف رابط دليل البرامج إن وُجد')); }
      this.setMode('m3u');
      return false;
    }
    if (this.mode === 'm3u') { this.setMode('xtream'); ins[1].value = ''; }
    if (p.username) {
      ins[0].value = p.server;
      ins[1].value = p.username;
      ins[2].value = p.password || '';
      UI.toast(tx('تم استخراج بيانات الدخول من الرابط'));
      return true;
    }
    return false;
  },

  onKey: function (k) {
    var self = this, cur = function () { return self.f >= -1 && self.f < 3 ? self.input(self.f) : null; };
    if (this.busy) return;
    /* the side the reading ends on: the show-password button there, the next kind of playlist */
    var endSide = I18N.en ? 'right' : 'left', startSide = I18N.en ? 'left' : 'right';
    switch (k) {
      case 'up': if (this.f > -2) { this.eye = false; this.f--; if (this.f === 2 && this.mode === 'm3u') this.f = 1; this.draw(); } break;
      case 'down': if (this.f < 3) { this.eye = false; this.f++; if (this.f === 2 && this.mode === 'm3u') this.f = 3; this.draw(); } break;
      case 'left': case 'right':
        if (this.f === -2) this.setMode(k === endSide ? 'm3u' : 'xtream');
        else if (this.f === 2) { this.eye = k === endSide; this.draw(); }
        break;
      case 'enter':
        if (this.f < 3) this.edit(); else this.submit();
        break;
      case 'imedone':
        if (cur()) cur().blur();
        if (this.f === 0 && this.afterServer()) this.f = 3;
        else if (this.f < 3) this.f++;
        if (this.f === 2 && this.mode === 'm3u') this.f = 3;
        this.draw();
        break;
      case 'imecancel':
        if (cur()) cur().blur();
        this.draw();
        break;
      case 'imeup':
        if (cur()) cur().blur();
        if (this.f > -2) this.f--;
        if (this.f === 2 && this.mode === 'm3u') this.f = 1;
        this.draw();
        break;
      case 'back':
        if (this.params.fromSettings || this.params.add) App.back();
        else App.exitConfirm();
        break;
    }
  },

  /* from the playlists screen: check the new playlist and keep it (the one in use stays).
     The check can be given up (إلغاء / Back); one that does not answer or does not work is
     never kept silently: the viewer chooses to fix it, keep it anyway, or leave. */
  addPlaylist: function (acc) {
    var self = this, off = false, req = null;
    UI.loading(true, tx('جاري التحقق من قائمة التشغيل...'), function () {
      off = true;
      if (req) req.abort();
      self.busy = false;
      if (Pair.enabled()) self.pairStatus('ready');
      self.draw();
    });
    req = Xtream.probe(acc, function (err) {
      if (off) return;
      self.busy = false;
      UI.loading(false);
      if (err && /^(auth|notlist|empty)$/.test(err.code)) {
        self.msg(Xtream.errorText(err));
        if (Pair.enabled()) self.pairStatus('ready');
        return;
      }
      if (err) {
        UI.confirm({
          title: tx('القائمة لا تعمل الآن'),
          text: Xtream.errorText(err) + (Store.activePlaylist() ? ' — ' + tx('ما زالت القائمة الحالية تعمل') : ''),
          buttons: [{ label: tx('تعديل البيانات'), value: 'fix' }, { label: tx('حفظها على أي حال'), value: 'keep' }, { label: tx('رجوع'), value: 'back' }],
          onSelect: function (v) {
            if (v === 'keep') self.keepPlaylist(acc, err);
            else if (v === 'back') { Pair.stop(); App.back(); }
            else { self.msg(Xtream.errorText(err)); if (Pair.enabled()) self.pairStatus('ready'); self.draw(); }
          }
        });
        return;
      }
      self.keepPlaylist(acc, null);
    });
  },

  keepPlaylist: function (acc, err) {
    var old = this.params.preset, before = Store.activePlaylist();
    var wasActive = !!(old && before && before.id === old.id);
    var named = this.typedName();
    if (named) acc.name = named;
    else if (old) acc.name = old.name;
    var pl = Store.savePlaylist(acc);
    if (old && pl.id !== old.id) {
      /* edited into a different link / account: it replaces the old entry */
      if (wasActive) Store.usePlaylist(pl.id);
      Store.removePlaylist(old.id);
    }
    Pair.stop();
    if (old) UI.toast(tx('تم حفظ التعديل') + ' ✓');
    else UI.toast(err ? tx('تمت إضافة القائمة لكنها لا تعمل حالياً') : tx('تمت إضافة قائمة التشغيل') + ' ✓');
    /* the playlist in use was edited: connect with the new details (that wait can be given up too) */
    if (wasActive) { Store.usePlaylist(pl.id); Xtream.clearCache(); App.reconnect(); return; }
    App.back({ added: pl.id, named: !!named });
  },

  typedName: function () { var n = U.$('lg-name'); return n ? String(n.value).replace(/^\s+|\s+$/g, '').slice(0, 40) : ''; },

  submit: function () {
    var self = this;
    var ins = this.inputs();
    this.afterServer();
    if (this.mode === 'm3u') {
      var link = Xtream.m3uLink(ins[0].value);
      if (!link) { this.msg(tx('اكتب رابط قائمة') + ' M3U'); this.f = 0; this.draw(); return; }
      var epg = String(ins[1].value).replace(/^\s+|\s+$/g, '');
      if (epg && !/^https?:\/\//i.test(epg)) epg = 'http://' + epg;
      this.go({ kind: 'm3u', url: link, epg: epg, name: this.typedName() || undefined });
      return;
    }
    var p = Xtream.parseServer(ins[0].value);
    var acc = {
      server: p.server,
      username: Xtream.clean(ins[1].value),
      password: Xtream.clean(ins[2].value)
    };
    if (this.typedName()) acc.name = this.typedName();
    if (!acc.server) { this.msg(tx('اكتب رابط السيرفر')); this.f = 0; this.draw(); return; }
    if (!acc.username) { this.msg(tx('اكتب اسم المستخدم')); this.f = 1; this.draw(); return; }
    if (!acc.password) { this.msg(tx('اكتب كلمة المرور')); this.f = 2; this.draw(); return; }
    this.go(acc);
  },

  go: function (acc) {
    var self = this;
    this.msg('');
    this.busy = true;
    if (this.params.add) { this.addPlaylist(acc); return; }
    UI.loading(true, acc.kind === 'm3u' ? tx('جاري تحميل قائمة التشغيل...') : tx('جاري تسجيل الدخول...'));
    Xtream.login(acc, function (err) {
      self.busy = false;
      UI.loading(false);
      if (err) {
        self.msg(Xtream.errorText(err));
        /* a failed attempt keeps the phone channel open for another try */
        if (Pair.enabled()) self.pairStatus('ready');
        return;
      }
      Store.setAccount(acc);
      Pair.stop();
      Xtream.clearCache();
      App.go('home', {}, { reset: true });
    });
  }
};

