    this.renderTop();
    this.renderNav();
    this.lastMin = -1;
    this.lastDay = '';
    this.tick();
    this.focus();
  };

  S.renderTop = function () {
    var h = this.expiryChip();
    for (var i = 0; i < TOP.length; i++) {
      h += '<div class="hm-btn" data-z="top" data-i="' + i + '">' + ICON[TOP[i].id] + '<span>' + TOP[i].name + '</span></div>';
    }
    U.$('hm-actions').innerHTML = h;
  };

  S.expiryChip = function () {
    var inf = Xtream.info();
    if (!inf || !inf.user_info) return '';
    var exp = parseInt(inf.user_info.exp_date, 10);
    if (!(exp > 0)) return '<div class="hm-exp">' + tx('اشتراك غير محدود') + '</div>';
    var days = Math.max(0, Math.ceil((exp * 1000 - U.now()) / 86400000));
    return '<div class="hm-exp' + (days <= 7 ? ' warn' : '') + '"><i></i>' + tx('الاشتراك ينتهي بعد') + ' <b>' + days + '</b> ' + tx('يوم') + '</div>';
  };

  S.renderNav = function () {
    var h = '';
    for (var i = 0; i < NAV.length; i++) {
      var n = NAV[i];
      h += '<div class="hm-card c-' + n.id + '" data-z="nav" data-i="' + i + '">' +
        '<div class="hc-ico">' + ICON[n.id] + '</div>' +
        '<div class="hc-txt"><b>' + n.name + '</b><span>' + U.esc(n.sub) + '</span></div></div>';
    }
    U.$('hm-nav').innerHTML = h;
  };

  /* ---------------- clock and dates ---------------- */
  S.startTimers = function () {
    var self = this;
    clearInterval(this.tickTimer);
    this.tickTimer = setInterval(function () { self.tick(); }, 1000);
  };

  S.tick = function () {
    var d = SaudiTime.now();
    var min = d.getUTCHours() * 60 + d.getUTCMinutes();
    var day = d.getUTCFullYear() + '-' + d.getUTCMonth() + '-' + d.getUTCDate();
    if (min !== this.lastMin) {
      this.lastMin = min;
      var p = SaudiTime.parts12(d);
      U.$('hm-clock').innerHTML = p.time;
      U.$('hm-ampm').innerHTML = p.ampm;
      if (day !== this.lastDay) {
        this.lastDay = day;
        U.$('hm-date').innerHTML = U.esc(SaudiTime.gregorian(d));
        U.$('hm-hijri').innerHTML = ICON.moon + '<span>' + U.esc(SaudiTime.hijriText(d)) + '</span>';
      }
    }
  };

  /* ---------------- news ticker (sports by default) ---------------- */
  S.loadNews = function () {
    var self = this;
    var key = Store.getSettings().news;
    clearInterval(this.newsTimer);
    clearInterval(this.newsRefresh);
    this.newsKey = key;
    if (!key || key === 'off' || !News.SOURCES[key]) { this.news = []; this.drawNews(); return; }
    News.load(key, function (items) {
      if (self.newsKey !== key) return;
      var keepTitle = self.news.length ? self.news[self.newsIdx % self.news.length].title : null;
      self.news = items || [];
      self.newsIdx = 0;
      for (var i = 0; keepTitle && i < self.news.length; i++) if (self.news[i].title === keepTitle) self.newsIdx = i;
      self.drawNews();
    });
    this.newsTimer = setInterval(function () { self.nextNews(); }, 8000);
    this.newsRefresh = setInterval(function () { News.load(key, function (items) {
      if (items && items.length && self.newsKey === key) { self.news = items; self.newsIdx = 0; self.drawNews(); }
    }); }, 15 * 60000 + 5000);
  };

  S.drawNews = function () {
    var box = U.$('hm-news');
    U.toggleClass(this.el, 'hm-nonews', !this.news.length);
    if (!this.news.length) { box.innerHTML = ''; return; }
    var key = Store.getSettings().news;
    box.innerHTML = '<div class="nw-tag">' + ICON.news + '<span>' + tx('أخبار') + ' ' + U.esc(News.SOURCES[key] ? News.SOURCES[key].name : '') + '</span></div>' +
      '<div class="nw-box" id="nw-box"></div><div class="nw-idx" id="nw-idx"></div>';
    this.showNews(false);
  };

  S.showNews = function (animate) {
    var box = U.$('nw-box');
    if (!box || !this.news.length) return;
    var n = this.news[this.newsIdx % this.news.length];
    var meta = [n.source, News.ago(n.t)].join(' · ').replace(/^ · | · $/g, '');
    box.innerHTML = '<div class="nw-item' + (animate ? ' in' : '') + '"><b>' + U.esc(n.title) + '</b>' +
      (meta ? '<span>' + U.esc(meta) + '</span>' : '') + '</div>';
    U.$('nw-idx').innerHTML = (this.newsIdx % this.news.length + 1) + ' / ' + this.news.length;
  };

  S.nextNews = function () {
    if (this.news.length < 2) return;
    this.newsIdx = (this.newsIdx + 1) % this.news.length;
    this.showNews(true);
  };

  /* ---------------- focus + keys ---------------- */
  S.focus = function () {
    var els = this.el.querySelectorAll('[data-z]');
    for (var i = 0; i < els.length; i++) {
      var on = els[i].getAttribute('data-z') === this.zone && parseInt(els[i].getAttribute('data-i'), 10) === this.idx[this.zone];
      U.toggleClass(els[i], 'focused', on);
    }
  };

  S.move = function (d) {
    var z = this.zone, n = z === 'top' ? TOP.length : NAV.length, i = this.idx[z] + d;
    if (i < 0 || i >= n) return;
    this.idx[z] = i;
    this.focus();
  };

  S.onKey = function (k) {
    if (k === 'left') this.move(1);
    else if (k === 'right') this.move(-1);
    else if (k === 'up' && this.zone === 'nav') { this.zone = 'top'; this.focus(); }
    else if (k === 'down' && this.zone === 'top') { this.zone = 'nav'; this.focus(); }
    else if (k === 'enter') this.open();
    else if (k === 'back') { if (this.zone !== 'nav') { this.zone = 'nav'; this.focus(); } else App.exitConfirm(); }
  };

  S.open = function () {
    var i = this.idx[this.zone];
    if (this.zone === 'top') {
      if (TOP[i].id === 'settings') App.go('settings', {});
      else this.searchMenu();
    } else {
      App.go('browse', { type: NAV[i].id });
    }
  };

  S.searchMenu = function () {
    UI.menu({
      title: tx('البحث في'),
      items: [
        { label: tx('القنوات'), value: 'live' },
        { label: tx('الأفلام'), value: 'vod' },
        { label: tx('المسلسلات'), value: 'series' }
      ],
      onSelect: function (v) { if (v) App.go('browse', { type: v, search: true }); }
    });
  };
})();

