    saga: '<svg viewBox="0 0 24 24"><path d="M4 6H2v14c0 1.1.9 2 2 2h14v-2H4V6zm16-4H8c-1.1 0-2 .9-2 2v12c0 1.1.9 2 2 2h12c1.1 0 2-.9 2-2V4c0-1.1-.9-2-2-2zm-8 12.5v-9l6 4.5-6 4.5z"/></svg>'
  };

  var EMPTY = {
    __fav: tx('لا توجد عناصر في المفضلة — اضغط مطوّلاً على أي عنصر لإضافته'),
    __search: tx('المس «بحث» واكتب الاسم الذي تبحث عنه'),
    __cont: tx('لا يوجد شيء لمتابعته حتى الآن'),
    __top: tx('لم نجد في قائمتك شيئاً من قوائم الأفضل في التاريخ'),
    __saga: tx('لم نجد في قائمتك سلسلة أفلام فيها 3 أجزاء أو أكثر'),
    locked: tx('هذا القسم محمي برمز — اضغط OK وأدخل الرمز لفتحه'),
    other: tx('لا يوجد محتوى في هذا القسم')
  };

  var S = Screens.browse = {
    type: 'live',
    zone: 'side',          /* side | content | search */
    cats: [],
    curCat: null,
    items: [],
    favSet: {},
    reqId: 0,
    searchResults: [],
    query: '',
    bound: false
  };

  S.show = function (params) {
    var self = this;
    this.type = params.type || 'live';
    this.el.className = 'screen br-' + this.type;
    U.$('br-title').innerHTML = TITLES[this.type];
    U.$('br-cat').innerHTML = '';
    U.$('br-info').innerHTML = '';
    U.$('br-search').value = '';
    this.query = '';
    this.searchResults = [];
    this.items = [];
    this.curCat = null;
    this.moving = null;
    this.rawCats = [];
    this.buildFavSet();
    this.bindSearch();

    this.side = new VList(U.$('br-side'), {
      rows: 10, extra: 1, rowClass: 'srow',
      render: function (c, i) { return self.renderCat(c, i); },
      onFocus: function () { self.onSideFocus(); }
    });

    if (this.type === 'live') {
      this.list = new VList(U.$('br-content'), {
        rows: 8, extra: 1, rowClass: 'lrow',
        render: function (it, i) { return self.renderChannel(it, i); },
        onFocus: function (i, it) { self.onItemFocus(i, it); }
      });
    } else {
      /* wide car screen: as many poster columns as fit, spread over the whole width */
      var cols = 6, box = U.$('br-content');
      if (window.ANDROID_APP && box.clientWidth) {
        var wdt = box.clientWidth - 14;
        cols = Math.max(6, Math.floor((wdt + 30) / 226));
        box.style.setProperty('--cgap', Math.max(30, Math.floor((wdt - cols * 196) / (cols - 1))) + 'px');
      }
      this.list = new VList(U.$('br-content'), {
        cols: cols, rows: 2, extra: 1, rowClass: 'grow',
        render: function (it, i) { return self.renderPoster(it, i); },
        onFocus: function (i, it) { self.onItemFocus(i, it); }
      });
    }
    this.list.setItems([]);

    var specials = [
      { id: '__search', name: tx('بحث'), icon: 'search' },
      { id: '__fav', name: tx('المفضلة'), icon: 'star' }
    ];
    if (this.type !== 'live') specials.push({ id: '__cont', name: tx('متابعة المشاهدة'), icon: 'cont' }, { id: '__top', name: tx('الأعلى تقييماً'), icon: 'top' });
    if (this.type === 'vod') specials.push({ id: '__saga', name: tx('سلاسل الأفلام'), icon: 'saga' });
    specials.push({ id: '__all', name: ALL[this.type], icon: 'all' });
    this.specials = specials;

    this.cats = specials.slice();
    this.side.setItems(this.cats, 1);
    clearTimeout(this.catTimer);
    this.setZone('side');
    this.setState('loading');
    this.catsFailed = false;
    this.params = params;

    var my = ++this.reqId;
    Xtream.getCategories(this.type, function (err, cats) {
      if (my !== self.reqId) return;
      if (err) {
        self.catsFailed = true;
        self.setState('error', Xtream.errorText(err) + ' — ' + tx('اضغط OK لإعادة المحاولة'));
        return;
      }
      self.rawCats = cats;
      self.cats = specials.concat(Parental.arrange(self.type, cats));
      /* start on favourites / continue watching if they have something, else the first category */
      var start = specials.length < self.cats.length ? specials.length : 1;
      if (self.cats[start] && self.cats[start].locked && !Parental.isUnlocked()) start = specials.length - 1;
      if (self.type !== 'live' && Store.continueList(self.type).length) start = 2;
      else if (Store.getFavs(self.type).length) start = 1;
      /* the home screen can ask for a section (favourites) or for the search box */
      var want = params.search ? '__search' : params.start;
      self.inSaga = null;
      for (var w = 0; want && w < specials.length; w++) if (specials[w].id === want) start = w;
      self.side.setItems(self.cats, start);
      if (params.search) { self.openSearch(); return; }
      self.selectCat(start, !!params.start);
    });
  };

  S.resume = function (result) {
    this.buildFavSet();
    U.$('br-title').innerHTML = TITLES[this.type];
    var id = this.curCat && this.curCat.id;
    /* favourites / continue lists may have changed while we were away */
    if (id === '__fav' || id === '__cont') {
      var keep = this.list.index;
      this.items = Parental.filter(this.type, id === '__fav' ? Store.getFavs(this.type) : Store.continueList(this.type));
      this.list.setItems(this.items, keep);
      this.setState(this.items.length ? '' : 'empty', EMPTY[id]);
      if (!this.items.length) this.setZone('side');
    } else {
      this.list.refresh();
    }
    if (result && result.index !== undefined && this.items.length) this.list.focusTo(result.index);
    this.side.refresh();
    this.setZone(this.zone === 'search' ? 'side' : this.zone);
    this.updateCount();
  };

  S.hide = function () {
    clearTimeout(this.catTimer);
    clearTimeout(this.epgTimer);
    U.$('br-search').blur();
  };

  /* ---------------- rendering ---------------- */
  S.renderCat = function (c, i) {
    var cur = this.curCat && this.curCat.id === c.id ? ' cur' : '';
    var mv = this.moving !== null && this.moving === c.id ? ' moving' : '';
    return '<div class="sitem' + cur + mv + '" data-i="' + i + '">' +
      '<span class="sico">' + ICONS[mv ? 'move' : (c.icon || 'folder')] + '</span>' +
      '<span class="sname">' + U.esc(c.name) + '</span>' +
