        if (max > 0 && act >= max) { self.waitFree(title, d, n + 1); return; }
        p.startAt = self.time;
        self.start();
      });
    }, EVERY);
  };

  /* ---------------- a stream that dropped while playing ----------------
     The car's subscription allows ONE stream, and the provider keeps counting the dropped
     one for a while (up to a few minutes when the car's internet blinked). Starting again
     at once was refused as "busy on another device", so: free our side, wait a little
     longer each time, and try the same channel / the same moment again — about 4 minutes
     in all — then say so plainly. */
  var RECONNECT_WAITS = [3, 5, 8, 10, 15, 15, 20, 20, 30, 30, 30, 30, 30];   /* seconds */
  S.reconnect = function (detail) {
    var self = this, p = this.p, key = this.playKey(), n = p.reconn = (p.reconn || 0) + 1;
    Player.release();
    clearTimeout(this.reconnT);
    if (n > RECONNECT_WAITS.length) {
      p.reconn = 0; p.playingKey = null;
      this.center('');
      this.msg(tx('انقطع البث ولم يرجع'), tx('تأكد من اتصال الإنترنت ثم شغّل') + ' ' + (this.isLive() ? tx('القناة') : tx('الفيديو')) + ' ' + tx('مرة أخرى'), detail);
      this.showOSD(true);
      return;
    }
    var say = function () { self.msg(tx('انقطع البث — جارٍ إعادة الاتصال…'), tx('يعود التشغيل تلقائياً (محاولة') + ' ' + n + ')', ''); };
    this.center('buffer');
    say();
    this.reconnT = setTimeout(function () {
      if (App.current() !== 'player' || self.p !== p || self.playKey() !== key) return;
      if (!self.isLive()) p.startAt = self.time;
      p.late = true;
      self.start();
      if (p.reconn) { say(); self.center('buffer'); }
    }, RECONNECT_WAITS[n - 1] * 1000);
  };

  /* ---------------- a live channel that does not open ----------------
     First: is the subscription busy on another screen? If not, this copy of the channel is
     down at the provider: play another copy of the same channel (lists often carry several,
     e.g. "AR: beIN SPORTS 1 HD" and "BEIN (G) SPORTS 1 HD"), and when it works, put it in
     the favourites in place of the broken one. */
  function chKey(name) {
    var n = String(name || '').toLowerCase().replace(/\+/g, ' plus ').replace(/[|:\[\]()\-_.\/]/g, ' ').replace(/\s+/g, ' ').trim();
    n = n.replace(/^(ar|eg|sa|ae|kw|qa|bh|om|jo|lb|ma|dz|tn|iq|sy|ly|sd|ps|ye|mena|arab|arabic) /, '');
    n = n.replace(/\b(hd|fhd|uhd|sd|4k|8k|hevc|h265|h264|backup|bk|vip|raw|[a-z])\b/g, ' ').replace(/\bsports\b/g, 'sport');
    return n.replace(/\s+/g, ' ').trim();
  }
  function chScore(name) {
    var n = String(name || '').toLowerCase(), sc = 0;
    if (/\bhd\b/.test(n)) sc += 3; else if (/\bfhd\b/.test(n)) sc += 2;
    if (/\bsd\b|\blow\b/.test(n)) sc -= 3;
    if (/4k|uhd|hevc|h265/.test(n)) sc -= 4;
    return sc;
  }
  S.liveFailed = function (detail) {
    var self = this, p = this.p, ch = this.channel(), d = String(detail || ''), title = tx('تعذّر تشغيل هذه القناة حالياً');
    function here() { return App.current() === 'player' && self.p === p && self.channel() === ch && Player.state() === 'error'; }
    function say(sub) { if (here()) self.msg(title, sub, d); }
    this.center('');
    this.msg(title, tx('لحظة… جارٍ معرفة السبب'), d);
    this.showOSD(true);
    var acc = Xtream.account();
    if (!acc) { say(tx('جرّب قناة أخرى أو غيّر صيغة البث من الإعدادات')); return; }
    Player.release();            /* so the provider's count no longer includes this screen's failed try */
    setTimeout(function () { if (here()) Xtream.probe(acc, onProbe); }, 3000);
    function onProbe(err, data) {
      if (!here()) return;
      var ui = data && data.user_info;
      var max = ui ? parseInt(ui.max_connections, 10) : 0, act = ui ? parseInt(ui.active_cons, 10) : 0;
      if (max > 0 && act >= max) { self.waitFree(title, d, 0); return; }
      self.tryOtherCopy(ch, function (ok) { if (!ok) say(tx('القناة متوقفة عند المزوّد الآن — جرّب قناة أخرى أو لاحقاً')); });
    }
  };
  S.tryOtherCopy = function (ch, cb) {
    var self = this, p = this.p, key = chKey(ch.name);
    p.tried = p.tried || {};
    p.tried[ch.id] = 1;
    if (!key) { cb(false); return; }
    Xtream.getStreams('live', null, function (err, all) {
      if (App.current() !== 'player' || self.p !== p) return;
      if (err || !all) { cb(false); return; }
      var c = [];
      for (var i = 0; i < all.length; i++) if (!p.tried[all[i].id] && chKey(all[i].name) === key) c.push(all[i]);
      if (!c.length || (p.altCount || 0) >= 3) { cb(false); return; }
      c.sort(function (a, b) { return chScore(b.name) - chScore(a.name); });
      var alt = c[0];
      p.tried[alt.id] = 1;
      p.altCount = (p.altCount || 0) + 1;
      if (!p.altFrom) p.altFrom = { ch: ch, fav: Store.isFav('live', ch.id) };
      UI.toast(tx('هذه النسخة من القناة متوقفة — جارٍ تجربة نسخة أخرى:') + ' ' + alt.name, 5000);
      p.list[p.index] = alt;
      self.start();
      cb(true);
    });
  };
  S.altWorked = function () {
    var p = this.p, from = p.altFrom, ch = this.channel();
    p.altFrom = null; p.altCount = 0; p.tried = {};
    if (from.fav && Store.replaceFav && Store.replaceFav(from.ch.id, ch)) {
      UI.toast(tx('تم التشغيل — ووُضعت هذه النسخة في المفضلة بدل القديمة'), 5000);
      this.renderOSD();
    }
  };

  /* movie or episode reached the end */
  S.finished = function () {
    this.save(true);
    if (this.p.kind === 'episode' && Store.getSettings().autoNext) {
      var n = this.nextEp(1);
      if (n) {
        UI.toast(tx('تشغيل الحلقة التالية...'));
        this.p.seasonIdx = n.s; this.p.epIdx = n.e; this.p.startAt = 0;
        this.start();
        return;
      }
    }
    this.exit();
  };

  S.nextEp = function (d) {
    var ss = this.p.seasons, s = this.p.seasonIdx, e = this.p.epIdx + d;
    if (e >= 0 && e < ss[s].episodes.length) return { s: s, e: e };
    if (d > 0 && s + 1 < ss.length && ss[s + 1].episodes.length) return { s: s + 1, e: 0 };
    if (d < 0 && s - 1 >= 0 && ss[s - 1].episodes.length) return { s: s - 1, e: ss[s - 1].episodes.length - 1 };
    return null;
  };

  /* remember the position of movies / episodes */
  S.save = function (ended) {
    var p = this.p;
    if (!p || this.isLive()) return;
    var pos = Player.getTime() || this.time;
    var dur = Player.getDuration() || this.dur;
    if (!dur) return;
    if (!ended && pos < 5000) return;
    var done = ended || pos > dur * 0.93;
    if (p.kind === 'movie') {
      Store.setHist('m:' + p.item.id, { pos: done ? 0 : pos, dur: dur, done: done, item: Store.slim(p.item) });
    } else {
      var ep = this.episode();
      Store.setHist('e:' + ep.id, { pos: done ? 0 : pos, dur: dur, done: done });
      Store.setHist('s:' + p.series.id, { episodeId: ep.id, season: ep.season, num: ep.num, item: Store.slim(p.series) });
    }
  };

  S.exit = function () {
    this.reportLive();
    this.save();
    this.clearTimers();
    Player.stop();
    var p = this.p;
    if (p.kind === 'live') App.back({ index: p.index });
    else if (p.kind === 'episode') App.back({ seasonIdx: p.seasonIdx, epIdx: p.epIdx });
    else App.back();
  };

  /* TV app hidden (Home button / source change) and shown again */
  S.visibility = function (hidden) {
    if (hidden) {
      this.reportLive();
      this.save();
      this.resumeAt = Player.getTime() || this.time;
      clearInterval(this.saveTimer);
      Player.stop();
    } else if (this.p) {
      if (!this.isLive()) this.p.startAt = this.resumeAt || 0;
      this.start();
    }
  };

  /* ---------------- live helpers ---------------- */
  /* remote diagnostics: how fast the channel opened and how often it froze */
  S.reportLive = function () {
    if (!this.p || !this.isLive()) return;
    var st = Player.stats();
    if (!st.live || st.secs < 8) return;
    S.liveReports = (S.liveReports || 0) + 1;
    if (S.liveReports > 12) return;
    Diag.send('live' + S.liveReports, 'fmt=' + this.fmt + ' start=' + st.startMs + 'ms stalls=' + st.stalls +
      ' frozen=' + Math.round(st.stallMs / 1000) + 's of ' + st.secs + 's');
  };

  S.zapTo = function (i) {
    var n = this.p.list.length;
    if (!n) return;
    this.reportLive();
    this.p.index = (i + n) % n;
    this.start();
  };

  S.loadEpg = function () {
    var self = this, ch = this.channel();
    Xtream.getShortEpg(ch.id, function (err, list) {
      if (!self.p || !self.isLive() || self.channel().id !== ch.id) return;
      self.epg = err ? [] : list;
      self.renderBottom();
    });
  };

  S.openZap = function () {
    this.zapOpen = true;
    U.addClass(U.$('pl-zap'), 'open');
    U.$('pl-zap-head').innerHTML = '<b>' + U.esc(this.p.catName || tx('القنوات')) + '</b><span>' + this.p.list.length + ' ' + tx('قناة') + '</span>';
    this.zap.setActive(true);
    this.zap.setItems(this.p.list, this.p.index);
    this.hideOSD();
    this.armZap();
  };

  S.closeZap = function (instant) {
    this.zapOpen = false;
    clearTimeout(this.zapTimer);
    U.removeClass(U.$('pl-zap'), 'open');
  };

  S.armZap = function () {
    var self = this;
    clearTimeout(this.zapTimer);
    this.zapTimer = setTimeout(function () { self.closeZap(); }, 12000);
  };

  S.numKey = function (d) {
    var self = this;
    this.numBuf = (this.numBuf + d).substr(-4);
    var el = U.$('pl-num');
    el.innerHTML = this.numBuf;
    el.style.display = 'block';
    clearTimeout(this.numTimer);
    this.numTimer = setTimeout(function () {
      var buf = self.numBuf;
      self.numBuf = '';
      el.style.display = 'none';
      var l = self.p.list;
      for (var i = 0; i < l.length; i++) {
        if (String(l[i].num) === buf) { self.zapTo(i); return; }
      }
      UI.toast(tx('القناة رقم') + ' ' + buf + ' ' + tx('غير موجودة في هذه القائمة'));
    }, 1600);
  };

  /* ---------------- VOD seeking ---------------- */
  /* left / right move the position; the jump happens by itself a moment
     after the last press (holding the key moves further before jumping) */
  S.seekBy = function (sec, fixed) {
    var self = this;
    var dur = Player.getDuration() || this.dur;
    if (!dur) return;
    var first = this.seekTarget === null;
    var base = first ? (Player.getTime() || this.time) : this.seekTarget;
    /* holding the key moves faster: 10 s, then 30 s, then 60 s steps */
    var dir = sec > 0 ? 1 : -1;
    if (first || dir !== this.seekDir) this.seekSteps = 0;
    this.seekDir = dir;
    this.seekSteps++;
    var step = fixed || Math.abs(sec) > 10 ? Math.abs(sec) : (this.seekSteps > 12 ? 60 : (this.seekSteps > 5 ? 30 : 10));
    this.seekTarget = U.clamp(base + dir * step * 1000, 0, dur - 3000);
    this.showOSD(true);
    this.updateProgress(this.seekTarget);
    this.seekHint();
    clearTimeout(this.seekTimer);
    this.seekTimer = setTimeout(function () { self.commitSeek(); }, 800);
  };

  S.seekHint = function () {
    var hint = U.$('pl-keyhint');
    if (!hint || this.seekTarget === null) return;
    var d = Math.round((this.seekTarget - (Player.getTime() || this.time)) / 1000);
    var txt = (d >= 0 ? '+' : '-') + U.fmtTime(Math.abs(d) * 1000);
    hint.innerHTML = (d >= 0 ? tx('تقديم إلى') + ' ' : tx('ترجيع إلى') + ' ') + U.fmtTime(this.seekTarget) +
      ' <span class="seek-delta" dir="ltr">(' + txt + ')</span>';
  };

  S.commitSeek = function () {
    if (this.seekTarget === null) return false;
    clearTimeout(this.seekTimer);
    var t = this.seekTarget;
    this.seekTarget = null;
    this.time = t;
    Player.seekTo(t);
    this.updateProgress();
    this.drawBar();
    this.showOSD();
    return true;
  };

  S.cancelSeek = function () {
    if (this.seekTarget === null) return false;
    clearTimeout(this.seekTimer);
    this.seekTarget = null;
    this.updateProgress();
    this.drawBar();
    this.showOSD();
    return true;
  };


  /* ---------------- OSD rendering ---------------- */
  S.renderOSD = function () {
    var p = this.p, h = '';
    if (p.kind === 'live') {
      var ch = this.channel();
      var fav = Store.isFav('live', ch.id) ? '<span class="pl-fav">' + STAR + '</span>' : '';
      h = '<div class="pl-ch"><span class="pl-chnum">' + U.esc(ch.num || (p.index + 1)) + '</span>' +
        U.img(ch.icon, ch.name, 'pl-logo') +
        '<div><div class="pl-title">' + U.esc(ch.name) + fav + '</div>' +
        '<div class="pl-subtitle">' + U.esc(p.catName || '') + '</div></div></div>';
    } else if (p.kind === 'movie') {
      h = '<div class="pl-ch"><div><div class="pl-title">' + U.esc(p.item.name) + '</div>' +
        '<div class="pl-subtitle">' + tx('فيلم') + '</div></div></div>';
    } else {
      var ep = this.episode(), s = p.seasons[p.seasonIdx];
      h = '<div class="pl-ch"><div><div class="pl-title">' + U.esc(p.series.name) + '</div>' +
        '<div class="pl-subtitle">' + tx('الموسم') + ' ' + U.esc(s.num) + ' · ' + tx('الحلقة') + ' ' + U.esc(ep.num) +
        (ep.title ? ' — ' + U.esc(ep.title) : '') + '</div></div></div>';
    }
    if (p.kind === 'live') {
      U.$('pl-top').innerHTML = h + '<div class="clock">' + UI.clockText() + '</div>';
    } else {
      /* movies / episodes: round option buttons at the top */
      this.tools = this.vodTools();
      var t = '<div class="pl-tools">';
      for (var i = 0; i < this.tools.length; i++) {
        t += '<div class="pl-tool" data-t="' + i + '">' + this.tools[i].icon + '<span class="tl">' + U.esc(this.tools[i].label) + '</span></div>';
      }
      t += '<div class="clock">' + UI.clockText() + '</div></div>';
      U.$('pl-top').innerHTML = h + t;
    }
    this.renderBottom();
  };

  S.renderBottom = function () {
    var h = '';
    if (this.isLive()) {
      if (this.epg.length) {
        var now = this.epg[0], next = this.epg[1];
        var pct = now.end > now.start ? U.clamp((U.now() - now.start) / (now.end - now.start), 0, 1) : 0;
        h += '<div class="pl-epg"><div class="pl-epg-now">' +
          '<span class="chip now">' + tx('الآن') + '</span><b>' + U.esc(now.title) + '</b>' +
          '<span class="pl-epg-time">' + U.fmtClock(new Date(now.start)) + ' - ' + U.fmtClock(new Date(now.end)) + '</span></div>' +
          '<div class="bar" dir="ltr"><i style="width:' + Math.round(pct * 100) + '%"></i></div>';
        if (next) h += '<div class="pl-epg-next"><span class="chip">' + tx('التالي') + '</span>' + U.esc(next.title) +
          '<span class="pl-epg-time">' + U.fmtClock(new Date(next.start)) + '</span></div>';
        h += '</div>';
      }
      var fav = Store.isFav('live', this.channel().id);
      this.barItems = [
        { a: 'channels', icon: ICON.list, label: tx('القنوات') },
        { a: 'audio', icon: ICON.audio, label: tx('الصوت') },
        { a: 'subs', icon: ICON.subs, label: tx('الترجمة'), dot: 'yellow' },
        { a: 'aspect', icon: ICON.aspect, label: tx('أبعاد الشاشة'), dot: 'blue' },
        { a: 'fav', icon: STAR, label: fav ? tx('إزالة من المفضلة') : tx('إضافة للمفضلة'), dot: 'red' }
      ];
      /* car screen: previous / next channel as worded buttons (next on the right, like the episodes) */
      if (window.ANDROID_APP && !window.IS_TV && this.p.list && this.p.list.length > 1) {
        this.barItems.unshift({ a: 'chNext', label: tx('القناة التالية'), words: true });
        this.barItems.push({ a: 'chPrev', label: tx('القناة السابقة'), words: true });
      }
      h += this.barHtml();
    } else {
      h += '<div class="pl-progress" dir="ltr">' +
        '<span class="pl-cur" id="pl-cur">00:00</span>' +
        '<div class="bar big"><i id="pl-fill"></i><b id="pl-knob"></b></div>' +
        '<span class="pl-dur" id="pl-dur">--:--</span></div>';
      /* media buttons, laid out left-to-right like every player */
      this.ctrls = this.vodCtrls();
      h += '<div class="pl-ctrls" dir="ltr">';
      for (var c = 0; c < this.ctrls.length; c++) {
        var b = this.ctrls[c];
        if (b.words) { h += '<div class="pl-c words" data-c="' + c + '"><span class="pw" dir="rtl">' + U.esc(b.label) + '</span></div>'; continue; }
        h += '<div class="pl-c ' + b.cls + '" data-c="' + c + '">' + b.icon + (b.ten ? '<b>10</b>' : '') +
          '<span class="tl">' + U.esc(b.label) + '</span></div>';
      }
      h += '</div><div class="pl-keyhint" id="pl-keyhint"></div>';
      this.barItems = [];
    }
    U.$('pl-bottom').innerHTML = h;
    if (this.isLive() && this.barIdx >= this.barItems.length) this.barIdx = this.barItems.length - 1;
    this.drawBar();
    this.updateProgress();
  };

  /* ---------------- bottom button bar (reach it with the arrows) ---------------- */
  S.barHtml = function () {
    var h = '<div class="pl-bar">';
    for (var i = 0; i < this.barItems.length; i++) {
      var b = this.barItems[i];
      if (b.words) { h += '<div class="pl-btn words" data-b="' + i + '"><span>' + U.esc(b.label) + '</span></div>'; continue; }
      h += '<div class="pl-btn" data-b="' + i + '">' + b.icon + '<span>' + U.esc(b.label) + '</span>' +
        (b.dot ? '<i class="dot ' + b.dot + '"></i>' : '') + '</div>';
    }
    return h + '</div><div class="pl-keyhint" id="pl-keyhint"></div>';
  };

  S.drawBar = function () {
    if (!this.isLive()) { this.drawVod(); return; }
    var btns = U.$('pl-bottom').querySelectorAll('.pl-btn');
    for (var i = 0; i < btns.length; i++) U.toggleClass(btns[i], 'focused', i === this.barIdx);
    var hint = U.$('pl-keyhint');
    if (!hint) return;
    if (this.barIdx >= 0) hint.innerHTML = '<span class="kb" dir="ltr">◀ ▶</span> ' + tx('تنقّل') + ' <span class="kb">OK</span> ' + tx('اختيار') + ' <span class="kb">▲</span> ' + tx('رجوع');
    else if (this.isLive()) hint.innerHTML = '<span class="kb" dir="ltr">▲ ▼</span> ' + tx('تغيير القناة') + ' <span class="kb" dir="ltr">◀ ▶</span> ' + tx('الخيارات') + ' <span class="kb">OK</span> ' + tx('قائمة القنوات');
    else hint.innerHTML = '<span class="kb" dir="ltr">◀ ▶</span> ' + tx('ترجيع / تقديم') + ' <span class="kb">OK</span> ' + tx('إيقاف / تشغيل') + ' <span class="kb">▼</span> ' + tx('الخيارات');
    if (this.barIdx < 0 && this.seekTarget !== null) this.seekHint();
  };

  S.enterBar = function () {
    this.barIdx = 0;
    this.showOSD(true);
    this.drawBar();
    this.armBar();
  };

  S.leaveBar = function (hide) {
    this.barIdx = -1;
    this.vz = null;
    clearTimeout(this.barTimer);
    this.drawBar();
    if (hide) this.hideOSD(); else this.showOSD();
  };

  /* drop the focus after 10 s without a key */
  S.armBar = function () {
    var self = this;
    clearTimeout(this.barTimer);
    this.barTimer = setTimeout(function () { if (!UI.modal()) self.leaveBar(true); else self.armBar(); }, 10000);
  };

  /* a menu opened from the bar closed: come back to the bar */
  S.menuClosed = function () {
    if (this.barIdx < 0 || App.current() !== 'player') return;
    this.showOSD(true);
    this.drawBar();
    this.armBar();
  };

  S.barKey = function (k) {
    var n = this.barItems.length;
    this.armBar();
    switch (k) {
      case 'left': if (this.barIdx < n - 1) { this.barIdx++; this.drawBar(); } return true;
      case 'right': if (this.barIdx > 0) { this.barIdx--; this.drawBar(); } return true;
      case 'enter': this.barAction(this.barItems[this.barIdx].a); return true;
      case 'up': case 'back': this.leaveBar(false); return true;
      case 'down': if (this.isLive()) this.leaveBar(false); return true;
    }
    return false;
  };

  S.barAction = function (a) {
    switch (a) {
      case 'toggle':
        if (Player.state() === 'error') { this.p.startAt = this.time; this.start(); break; }
        Player.toggle(); this.showOSD(true);
        break;
      case 'prevEp': this.changeEpisode(-1); break;
      case 'nextEp': this.changeEpisode(1); break;
      case 'audio': this.audioMenu(); break;
      case 'subs': this.subsMenu(); break;
      case 'speed': this.speedMenu(); break;
      case 'aspect': this.aspectMenu(); break;
      case 'channels': this.barIdx = -1; this.openZap(); break;
      case 'chPrev': this.zapTo(this.p.index - 1); break;
      case 'chNext': this.zapTo(this.p.index + 1); break;
      case 'fav':
        var on = Store.toggleFav(this.channel());
        UI.toast(on ? tx('تمت إضافة القناة للمفضلة') : tx('تمت إزالة القناة من المفضلة'));
        this.renderOSD(); this.showOSD(true);
        break;
    }
  };

  S.changeEpisode = function (d) {
    if (this.p.kind !== 'episode') return;
    var n = this.nextEp(d);
    if (!n) { UI.toast(d > 0 ? tx('هذه آخر حلقة') : tx('هذه أول حلقة')); return; }
    this.save();
    this.p.seasonIdx = n.s; this.p.epIdx = n.e;
    var h = Store.getHist('e:' + this.episode().id);
    this.p.startAt = h && !h.done && h.pos > 30000 ? h.pos : 0;
    var keep = this.barIdx, kz = this.vz;
    this.start();
    if (keep >= 0) { this.barIdx = keep; this.vz = kz; this.showOSD(true); this.drawBar(); this.armBar(); }
  };

  /* ================= movies / episodes: top options + media buttons ================= */
  S.vodTools = function () {
    var t = [];
    if (this.p.kind === 'episode') t.push({ a: 'episodes', icon: ICON.eps, label: tx('الحلقات') });
    t.push({ a: 'audio', icon: ICON.audio, label: tx('الصوت') });
    t.push({ a: 'subs', icon: ICON.subs, label: tx('الترجمة') });
    if (Player.speedOk && Player.speedOk()) t.push({ a: 'speed', icon: ICON.speed, label: tx('السرعة') });
    t.push({ a: 'aspect', icon: ICON.aspect, label: tx('أبعاد الشاشة') });
    return t;
  };

  S.vodCtrls = function () {
    var ep = this.p.kind === 'episode', c = [];
    /* car screen: the episode buttons say what they do instead of showing an arrow */
    var words = !!(window.ANDROID_APP && !window.IS_TV);
    if (ep) c.push({ a: 'prevEp', icon: ICON.prev, cls: 'sm', label: tx('الحلقة السابقة'), words: words });
    c.push({ a: 'rw10', icon: ICON.replay, cls: 'md', ten: true, label: tx('رجوع 10 ث') });
    c.push({ a: 'toggle', icon: this.paused ? PLAY : PAUSE, cls: 'lg', label: this.paused ? tx('تشغيل') : tx('إيقاف مؤقت') });
    c.push({ a: 'ff10', icon: ICON.replay, cls: 'md ff', ten: true, label: tx('تقديم 10 ث') });
    if (ep) c.push({ a: 'nextEp', icon: ICON.next, cls: 'sm', label: tx('الحلقة التالية'), words: words });
    return c;
  };

  S.playIndex = function () {
    for (var i = 0; i < (this.ctrls || []).length; i++) if (this.ctrls[i].a === 'toggle') return i;
    return 0;
  };

  S.drawVod = function () {
    var i, el = U.$('pl-top').querySelectorAll('.pl-tool');
    for (i = 0; i < el.length; i++) U.toggleClass(el[i], 'focused', this.vz === 'top' && i === this.vt);
    el = U.$('pl-bottom').querySelectorAll('.pl-c');
    for (i = 0; i < el.length; i++) U.toggleClass(el[i], 'focused', this.vz === 'ctrl' && i === this.vc);
    var hint = U.$('pl-keyhint');
    if (!hint) return;
    if (this.seekTarget !== null) { this.seekHint(); return; }
    if (this.vz === 'ctrl') hint.innerHTML = '<span class="kb" dir="ltr">◀ ▶</span> ' + tx('تنقّل') + ' <span class="kb">OK</span> ' + tx('اختيار') + ' <span class="kb">▲</span> ' + tx('الخيارات فوق');
    else if (this.vz === 'top') hint.innerHTML = '<span class="kb" dir="ltr">◀ ▶</span> ' + tx('تنقّل') + ' <span class="kb">OK</span> ' + tx('اختيار') + ' <span class="kb">▼</span> ' + tx('أزرار التشغيل');
    else hint.innerHTML = '<span class="kb" dir="ltr">◀ ▶</span> ' + tx('ترجيع / تقديم') + ' <span class="kb">OK</span> ' + tx('إيقاف / تشغيل') + ' <span class="kb">▼</span> ' + tx('أزرار التشغيل') + ' <span class="kb">▲</span> ' + tx('الخيارات') +
      (this.p.kind === 'episode' ? ' <span class="kb green"></span> ' + tx('الحلقات') : '');
  };

  S.enterVod = function (z) {
    this.vz = z;
    this.barIdx = 0;
    if (z === 'ctrl') this.vc = this.playIndex();
    else this.vt = 0;
    this.showOSD(true);
    this.drawVod();
    this.armBar();
  };

  S.vodKey = function (k) {
    this.armBar();
    if (this.vz === 'ctrl') {
      var n = this.ctrls.length;
      if (k === 'left') { if (this.vc > 0) { this.vc--; this.drawVod(); } return true; }
      if (k === 'right') { if (this.vc < n - 1) { this.vc++; this.drawVod(); } return true; }
      if (k === 'up') { this.vz = 'top'; this.vt = this.vt || 0; this.drawVod(); return true; }
      if (k === 'down' || k === 'back') { this.leaveBar(k === 'down'); return true; }
      if (k === 'enter') { this.vodAction(this.ctrls[this.vc].a); return true; }
    } else if (this.vz === 'top') {
      var m = this.tools.length;
      if (k === 'left') { if (this.vt < m - 1) { this.vt++; this.drawVod(); } return true; }
      if (k === 'right') { if (this.vt > 0) { this.vt--; this.drawVod(); } return true; }
      if (k === 'down') { this.vz = 'ctrl'; if (this.vc === undefined || this.vc >= this.ctrls.length) this.vc = this.playIndex(); this.drawVod(); return true; }
      if (k === 'up' || k === 'back') { this.leaveBar(false); return true; }
      if (k === 'enter') { this.vodAction(this.tools[this.vt].a); return true; }
    }
    return false;
  };

  S.vodAction = function (a) {
    if (a === 'rw10') { this.seekBy(-10, true); return; }
    if (a === 'ff10') { this.seekBy(10, true); return; }
    if (a === 'episodes') { this.openEps(); return; }
    this.barAction(a);
  };

  /* ================= episodes panel (inside the player) ================= */
  S.openEps = function () {
    if (this.p.kind !== 'episode') return;
    var self = this;
    if (!this.epsList) {
      this.epsList = new VList(U.$('eps-list'), {
        rows: 5, extra: 1, rowClass: 'eprow',
        render: function (ep, i) { return self.renderEp(ep, i); }
      });
    }
    this.hideOSD();
    this.epsOpen = true;
    this.epsSeason = this.p.seasonIdx;
    U.addClass(U.$('pl-eps'), 'open');
    this.epsList.setActive(true);
    this.drawEps(this.p.epIdx);
  };

  S.closeEps = function () {
    if (!this.epsOpen) return;
    this.epsOpen = false;
    U.removeClass(U.$('pl-eps'), 'open');
    if (this.epsList) this.epsList.setActive(false);
  };

  S.drawEps = function (focus) {
    var ss = this.p.seasons, h = '';
    U.$('eps-head').innerHTML = '<div><b>' + U.esc(this.p.series.name) + '</b><span>' + ss.length +
      (ss.length > 1 ? ' ' + tx('مواسم') : ' ' + tx('موسم')) + '</span></div>';
    var first = Math.max(0, Math.min(this.epsSeason - 2, ss.length - 5));
    for (var i = first; i < ss.length; i++) {
      h += '<span class="eps-tab' + (i === this.epsSeason ? ' cur' : '') + (i === this.p.seasonIdx ? ' playing' : '') + '">' + tx('الموسم') + ' ' + U.esc(ss[i].num) + '</span>';
    }
    U.$('eps-seasons').innerHTML = (first > 0 ? '<span class="eps-more">‹</span>' : '') + h;
    this.epsList.setItems(ss[this.epsSeason].episodes, focus || 0);
  };

  S.renderEp = function (ep, i) {
    var playing = this.epsSeason === this.p.seasonIdx && i === this.p.epIdx;
    var h = Store.getHist('e:' + ep.id), badge = '', pct = 0;
    if (playing) {
      badge = '<span class="ep-now">' + tx('يعرض الآن') + '</span>';
      var d = Player.getDuration() || this.dur;
      pct = d ? (Player.getTime() || this.time) / d : 0;
    } else if (h && h.done) {
      badge = '<span class="ep-done">✓ ' + tx('تمت المشاهدة') + '</span>';
    } else if (h && h.dur && h.pos > 30000) {
      pct = h.pos / h.dur;
    }
    var dur = ep.duration ? String(ep.duration).replace(/^00:/, '') : '';
    return '<div class="epitem' + (playing ? ' playing' : '') + '" data-i="' + i + '">' +
      U.img(ep.image || this.p.series.icon, String(ep.num), 'epthumb') +
      '<div class="eptext"><div class="epnum">' + tx('الحلقة') + ' ' + U.esc(ep.num) + badge + '</div>' +
      '<div class="eptitle">' + U.esc(ep.title || (tx('الحلقة') + ' ' + ep.num)) + '</div>' +
      (dur ? '<div class="epdur">' + U.esc(dur) + '</div>' : '') + '</div>' +
      (pct > 0 ? '<span class="epprog"><i style="width:' + Math.round(U.clamp(pct, 0.02, 1) * 100) + '%"></i></span>' : '') +
      '</div>';
  };

  S.epsKey = function (k) {
    var ss = this.p.seasons;
    if (k === 'up' || k === 'down' || k === 'chup' || k === 'chdown') this.epsList.key(k);
    else if (k === 'left') { if (this.epsSeason < ss.length - 1) { this.epsSeason++; this.drawEps(0); } }
    else if (k === 'right') { if (this.epsSeason > 0) { this.epsSeason--; this.drawEps(0); } }
    else if (k === 'enter') {
      var e = this.epsList.index;
      if (this.epsSeason === this.p.seasonIdx && e === this.p.epIdx) { this.closeEps(); this.showOSD(); }
      else this.playEp(this.epsSeason, e);
    }
    else if (k === 'back' || k === 'green' || k === 'info') { this.closeEps(); this.showOSD(); }
    else if (k === 'playpause' || k === 'play' || k === 'pause') Player.toggle();
  };

  S.playEp = function (s, e) {
    this.closeEps();
    this.save();
    this.p.seasonIdx = s; this.p.epIdx = e;
    var h = Store.getHist('e:' + this.episode().id);
    this.p.startAt = h && !h.done && h.pos > 30000 ? h.pos : 0;
    this.start();
  };

  S.updateProgress = function (at) {
    if (this.isLive()) return;
    var fill = U.$('pl-fill');
    if (!fill) return;
    /* the controls are hidden: the page is not redrawn at all while the film plays (on phones,
       car screens and TVs every redraw of the page over the picture costs the picture smoothness);
       the bar is brought up to date when the controls come back */
    if (at === undefined && !this.osdVisible()) return;
    var dur = Player.getDuration() || this.dur;
    var t = at !== undefined ? at : this.time;
    var pct = dur ? U.clamp(t / dur, 0, 1) * 100 : 0;
    fill.style.width = pct + '%';
    U.$('pl-knob').style.left = pct + '%';
    U.$('pl-cur').innerHTML = U.fmtTime(t);
    U.$('pl-dur').innerHTML = dur ? U.fmtTime(dur) : '--:--';
    U.toggleClass(U.$('pl-cur'), 'seeking', at !== undefined);
  };

  S.showOSD = function (sticky) {
    var self = this;
    var top = U.$('pl-top').querySelector('.clock');
    if (top) top.innerHTML = UI.clockText();
    var was = this.osdVisible();
    U.addClass(U.$('pl-osd'), 'show');
    if (!was && this.seekTarget === null) this.updateProgress();
    clearTimeout(this.osdTimer);
    if (!sticky && !this.paused && this.barIdx < 0) this.osdTimer = setTimeout(function () { self.hideOSD(); }, 5000);
  };

  S.hideOSD = function () {
    clearTimeout(this.osdTimer);
    if (this.barIdx >= 0) { this.barIdx = -1; this.vz = null; clearTimeout(this.barTimer); this.drawBar(); }
    U.removeClass(U.$('pl-osd'), 'show');
  };

  S.osdVisible = function () { return U.$('pl-osd').className.indexOf('show') !== -1; };

  S.center = function (what) {
    var el = U.$('pl-center');
    this.bufferShown = what === 'buffer';
    if (what === 'buffer') el.innerHTML = '<div class="spinner"></div>';
    else if (what === 'pause') el.innerHTML = '<div class="pl-bigicon">' + PAUSE + '</div>';
    else el.innerHTML = '';
  };

  S.msg = function (title, sub, code) {
    var el = U.$('pl-msg');
    if (!title) { el.style.display = 'none'; return; }
    el.innerHTML = '<b>' + U.esc(title) + '</b>' + (sub ? '<span>' + U.esc(sub) + '</span>' : '') +
      (code ? '<i class="pl-code" dir="ltr">' + U.esc(String(code).slice(0, 60)) + '</i>' : '');
    el.style.display = 'block';
  };

  S.subtitle = function (text, ms) {
    var el = U.$('pl-sub');
    clearTimeout(this.subTimer);
    if (!text) { el.innerHTML = ''; el.style.display = 'none'; return; }
    el.innerHTML = U.esc(text).replace(/\n/g, '<br>');
    el.style.display = 'block';
    this.subTimer = setTimeout(function () { el.style.display = 'none'; }, ms > 0 ? ms : 4000);
  };

  /* ---------------- aspect ratio menu (live preview while moving) ---------------- */
  S.aspectMenu = function () {
    var cur = Player.aspectKey();
    var list = Player.aspectList(), items = [];
    for (var i = 0; i < list.length; i++) {
      items.push({ label: list[i].name, sub: list[i].desc, value: list[i].key, selected: list[i].key === cur });
    }
    var self = this, fromBar = this.barIdx, fromZone = this.vz, first = true;
    U.removeClass(U.$('pl-osd'), 'show');           /* keep the picture clear */
    UI.menu({
      title: tx('أبعاد الشاشة'), items: items, side: true, closeKey: 'blue',
      hint: tx('يُطبَّق التغيير فوراً أثناء التنقل ▲▼ · OK أو رجوع للإغلاق'),
      /* every move applies (and saves) the mode right away */
      onFocus: function (v) {
        if (first) { first = false; return; }      /* the menu opening is not a move */
        Player.setAspect(v);
        if (Player.aspectZoom(v) > 1 && !Player.zoomWorks()) UI.toast(tx('التكبير غير مدعوم على هذا التلفزيون'));
      },
      onSelect: function (v) {
        if (v !== null && v !== Player.aspectKey()) Player.setAspect(v);
        UI.toast(tx('أبعاد الشاشة:') + ' ' + Player.aspectName());
        self.barIdx = fromBar;
        self.vz = fromZone;
        self.menuClosed();
      }
    });
  };

  /* ---------------- playback speed ---------------- */
  S.speedMenu = function () {
    var self = this, cur = Player.getSpeed ? Player.getSpeed() : 1, items = [];
    var L = [[0.5, '0.5×  ' + tx('أبطأ')], [0.75, '0.75×'], [1, tx('عادية')], [1.25, '1.25×'], [1.5, '1.5×'], [2, '2×  ' + tx('أسرع')]];
    for (var i = 0; i < L.length; i++) items.push({ label: L[i][1], value: L[i][0], selected: L[i][0] === cur });
    UI.menu({
      title: tx('سرعة التشغيل'), items: items,
      onSelect: function (v) {
        if (v !== null && v !== cur) {
          if (Player.setSpeed(v)) UI.toast(v === 1 ? tx('السرعة عادية') : tx('السرعة') + ' ' + v + '×');
          else UI.toast(tx('تغيير السرعة غير متاح مع هذا المشغل'));
        }
        self.menuClosed();
      }
    });
  };

  /* ---------------- tracks ---------------- */
  S.audioMenu = function () {
    var self = this;
    var tr = Player.getTracks('AUDIO');
    if (tr.length < 2) { UI.toast(tr.length ? tx('يوجد مسار صوت واحد فقط') : tx('لا توجد مسارات صوت إضافية')); return; }
    var items = [];
    for (var i = 0; i < tr.length; i++) items.push({ label: tr[i].label, value: tr[i].index, selected: tr[i].selected });
    UI.menu({
      title: tx('مسار الصوت'), items: items,
      onSelect: function (v) { if (v !== null && Player.selectTrack('AUDIO', v)) UI.toast(tx('تم تغيير الصوت')); self.menuClosed(); }
    });
  };

  S.subsMenu = function () {
    var self = this;
    var tr = Player.getTracks('TEXT');
    if (!tr.length) { UI.toast(tx('لا توجد ترجمة مدمجة في هذا المحتوى')); return; }
    var items = [{ label: tx('بدون ترجمة'), value: -1, selected: !Player.subtitlesOn() }];
    for (var i = 0; i < tr.length; i++) items.push({ label: tr[i].label, value: tr[i].index, selected: tr[i].selected });
    UI.menu({
      title: tx('الترجمة'), items: items,
      onSelect: function (v) {
        if (v === -1) { Player.subtitlesOff(); self.subtitle(''); UI.toast(tx('تم إيقاف الترجمة')); }
        else if (v !== null && Player.selectTrack('TEXT', v)) UI.toast(tx('تم تفعيل الترجمة'));
        self.menuClosed();
      }
    });
  };

  /* ---------------- keys ---------------- */
  S.onKey = function (k, e) {
    var live = this.isLive();

    /* episodes panel open: it gets the keys */
    if (this.epsOpen) { this.epsKey(k); return; }

    /* the bottom button bar has the arrows / OK while it is focused */
    if (live && this.barIdx >= 0 && !this.zapOpen && this.barKey(k)) return;
    if (!live && this.vz && this.vodKey(k)) return;

    /* a jump is about to happen: OK does it now, Back cancels it */
    if (!live && this.seekTarget !== null) {
      if (k === 'enter') { this.commitSeek(); return; }
      if (k === 'back') { this.cancelSeek(); return; }
    }

    if (k === 'back' || k === 'stop') {
      if (this.zapOpen && k === 'back') { this.closeZap(); return; }
      this.exit();
      return;
    }
    if (k === 'blue') { this.aspectMenu(); return; }
    if (k === 'green') { if (this.p.kind === 'episode') this.openEps(); else this.audioMenu(); return; }
    if (k === 'yellow') { this.subsMenu(); return; }
    if (k === 'info') { if (this.osdVisible()) this.hideOSD(); else this.showOSD(); return; }

    if (live) {
      if (this.zapOpen) {
        this.armZap();
        if (k === 'up' || k === 'down' || k === 'chup' || k === 'chdown') this.zap.key(k);
        else if (k === 'enter') {
          var i = this.zap.index;
          this.closeZap();
          if (i !== this.p.index) this.zapTo(i); else this.showOSD();
        } else if (k === 'left') this.closeZap();
        return;
      }
      switch (k) {
        case 'up': case 'chup': this.zapTo(this.p.index + 1); break;
        case 'down': case 'chdown': this.zapTo(this.p.index - 1); break;
        case 'enter': this.openZap(); break;
        case 'left': case 'right': this.enterBar(); break;
        case 'digit': this.numKey(Keys.digit(e)); break;
        case 'red':
          var on = Store.toggleFav(this.channel());
          UI.toast(on ? tx('تمت إضافة القناة للمفضلة') : tx('تمت إزالة القناة من المفضلة'));
          this.renderOSD(); this.showOSD();
          break;
        case 'playpause': case 'play': case 'pause': this.showOSD(); break;
      }
      return;
    }

    /* movies / episodes */
    switch (k) {
      case 'enter': case 'playpause':
        if (Player.state() === 'error') { this.p.startAt = this.time; this.start(); break; }
        Player.toggle(); this.showOSD(); break;
      case 'play': Player.resume(); this.showOSD(); break;
      case 'pause': Player.pause(); break;
      case 'right': this.seekBy(10); break;
      case 'left': this.seekBy(-10); break;
      case 'ff': this.seekBy(60); break;
      case 'rw': this.seekBy(-60); break;
      case 'down': this.enterVod('ctrl'); break;
      case 'up': this.enterVod('top'); break;
      case 'chup': this.changeEpisode(1); break;
      case 'chdown': this.changeEpisode(-1); break;
    }
  };
})();

