    aspect: '<svg viewBox="0 0 24 24" style="fill:none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="5" width="18" height="14" rx="3"/><path d="M7 12V9h3M17 12v3h-3"/></svg>',
    speed: '<svg viewBox="0 0 24 24" style="fill:none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M5 18a8 8 0 1 1 14 0"/><path d="M12 14l4-4"/></svg>',
    eps: '<svg viewBox="0 0 24 24" style="fill:none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="4" width="14" height="12" rx="2.5"/><path d="M21 8v10a2 2 0 0 1-2 2H7"/><path d="M8.5 7.5v5l4-2.5z"/></svg>',
    star: '<svg viewBox="0 0 24 24"><path d="M12 17.3l6.2 3.7-1.6-7 5.4-4.7-7.2-.6L12 2 9.2 8.7 2 9.3l5.4 4.7-1.6 7z"/></svg>',
    fill: '<svg viewBox="0 0 24 24" style="fill:none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M4 9V4h5M20 9V4h-5M4 15v5h5M20 15v5h-5"/></svg>',
    fit: '<svg viewBox="0 0 24 24" style="fill:none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M9 4v5H4M15 4v5h5M9 20v-5H4M15 20v-5h5"/></svg>',
    starO: '<svg viewBox="0 0 24 24" style="fill:none" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round"><path d="M12 17.3l6.2 3.7-1.6-7 5.4-4.7-7.2-.6L12 2 9.2 8.7 2 9.3l5.4 4.7-1.6 7z"/></svg>'
  };

  var box = null;
  function el() {
    if (box) return box;
    box = document.createElement('div');
    box.id = 'tpl';
    document.body.appendChild(box);
    bindBar();
    return box;
  }
  function esc(s) { return U.esc(s); }
  function dock(a, icon, label, extra) {
    return '<button type="button" class="tp-ctl tp-dk' + (extra || '') + '" data-tp="' + a + '">' + icon + '<span>' + esc(label) + '</span></button>';
  }
  function btn(a, icon, label, cls) {
    return '<button type="button" class="tp-ctl ' + (cls || 'tp-ib') + '" data-tp="' + a + '" aria-label="' + esc(label) + '">' + icon + '</button>';
  }

  /* ---------------- drawing ---------------- */
  S.tpRender = function () {
    var p = this.p, b = el(), live = this.isLive(), h = '', name = '', sub = '', logo = '';
    if (!p) return;
    if (live) {
      var ch = this.channel();
      name = ch.name;
      sub = (ch.num ? ch.num + ' · ' : '') + (p.catName || '');
      logo = '<span class="tp-logo">' + T.pic(ch.icon, ch.name, 'logo') + '</span>';
    } else if (p.kind === 'movie') {
      name = p.item.name;
    } else {
      var ep = this.episode(), s = p.seasons[p.seasonIdx];
      name = p.series.name;
      sub = tx('الموسم') + ' ' + s.num + ' · ' + tx('الحلقة') + ' ' + ep.num + (ep.title && ep.title.indexOf(p.series.name) === -1 ? ' · ' + ep.title : '');
    }
    /* the round buttons at the top */
    var tools = btn('audio', I.audio, tx('الصوت')) + btn('subs', I.subs, tx('الترجمة')) + (live ? '' : btn('aspect', I.aspect, tx('أبعاد الشاشة')));
    if (!live && this.speedMenu && Player.speedOk && Player.speedOk()) tools += btn('speed', I.speed, tx('السرعة'));
    if (p.kind === 'episode') tools += btn('episodes', I.eps, tx('الحلقات'));
    if (live) tools += btn('fav', Store.isFav('live', this.channel().id) ? I.star : I.starO, tx('المفضلة'), 'tp-ib' + (Store.isFav('live', this.channel().id) ? ' on' : ''));

    h += '<div class="tp-shade top"></div><div class="tp-shade bot"></div>';
    h += '<div class="tp-top">' + btn('back', I.back, tx('رجوع'), 'tp-ib tp-back') + logo +
      '<div class="tp-tt"><b>' + esc(name) + '</b>' + (sub ? '<span>' + esc(sub) + '</span>' : '') + '</div>' +
      '<div class="tp-tools">' + tools + '</div><span class="tp-clock" id="tp-clock">' + UI.clockText() + '</span></div>';

    /* middle: left to right like every player */
    if (!live) {
      var err = Player.state() === 'error';
      h += '<div class="tp-mid" dir="ltr">' + btn('rw10', I.rw + '<i>10</i>', tx('رجوع 10 ثوانٍ'), 'tp-c seek') +
        btn('toggle', this.paused || err ? I.play : I.pause, this.paused ? tx('تشغيل') : tx('إيقاف مؤقت'), 'tp-c big') +
        btn('ff10', I.ff + '<i>10</i>', tx('تقديم 10 ثوانٍ'), 'tp-c seek') + '</div>';
    }

    h += '<div class="tp-bot">';
    if (live) {
      if (this.epg && this.epg.length) {
        var now = this.epg[0], nx = this.epg[1];
        var pct = now.end > now.start ? U.clamp((U.now() - now.start) / (now.end - now.start), 0, 1) : 0;
        h += '<div class="tp-epg"><div class="tp-now"><span class="tp-chip">' + tx('الآن') + '</span><b>' + esc(now.title) + '</b>' +
          '<span class="tp-time" dir="ltr">' + U.fmtClock(new Date(now.start)) + ' - ' + U.fmtClock(new Date(now.end)) + '</span></div>' +
          '<div class="tp-line" dir="ltr"><i style="width:' + Math.round(pct * 100) + '%"></i></div>' +
          (nx ? '<div class="tp-next"><span>' + tx('التالي') + '</span>' + esc(nx.title) + ' <span class="tp-time" dir="ltr">' + U.fmtClock(new Date(nx.start)) + '</span></div>' : '') + '</div>';
      }
      /* the buttons, in one tidy bar: previous · channels · next · picture size */
      var many = p.list && p.list.length > 1;
      h += '<div class="tp-dock">' +
        (many ? dock('chPrev', I.next, tx('القناة السابقة')) : '') +
        dock('channels', I.list, tx('القنوات')) +
        (many ? dock('chNext', I.prev, tx('القناة التالية')) : '') +
        '<i class="tp-sep"></i>' + dock('aspect', I.aspect, tx('أبعاد الشاشة')) + '</div>';
    } else {
      if (p.kind === 'episode') {
        h += '<div class="tp-eprow">' + btn('nextEp', I.next + '<span>' + tx('الحلقة التالية') + '</span>', tx('الحلقة التالية'), 'tp-pill') +
          btn('prevEp', I.prev + '<span>' + tx('السابقة') + '</span>', tx('الحلقة السابقة'), 'tp-pill dim') + '</div>';
      }
      h += '<div class="tp-prog" dir="ltr"><span id="tp-cur">00:00</span>' +
        '<div class="tp-bar tp-ctl" id="tp-bar"><div class="tp-track"><i id="tp-fill"></i></div><b id="tp-knob"></b></div>' +
        '<span id="tp-dur">--:--</span></div>';
    }
    h += '</div>';
    b.className = (live ? 'live' : 'vod') + (this.osdVisible() ? ' show' : '');
    b.innerHTML = h;
    this.tpProgress();
  };

  S.tpProgress = function (at) {
    if (!box || this.isLive()) return;
    var fill = U.$('tp-fill');
    if (!fill) return;
    var dur = Player.getDuration() || this.dur;
    if (at === undefined && this.seekTarget !== null) at = this.seekTarget;
    if (at === undefined && this.tpDrag !== undefined && this.tpDrag !== null) at = this.tpDrag;
    var t = at !== undefined ? at : this.time;
    var pct = dur ? U.clamp(t / dur, 0, 1) * 100 : 0;
    fill.style.width = pct + '%';
    U.$('tp-knob').style.left = pct + '%';
    U.$('tp-cur').innerHTML = U.fmtTime(t);
    U.$('tp-dur').innerHTML = dur ? U.fmtTime(dur) : '--:--';
    U.toggleClass(U.$('tp-cur'), 'seeking', at !== undefined);
  };

  /* one press between the whole picture and a full screen (every mode is in «أبعاد الشاشة») */
  S.zoomBtn = function (small) {
    var full = Player.aspectKey && Player.aspectKey() !== 'fit';
    if (small) return '<button type="button" class="tp-ctl tp-ib tp-zoom" data-tp="zoom" aria-label="' + (full ? tx('الصورة كاملة') : tx('ملء الشاشة')) + '">' + (full ? I.fit : I.fill) + '</button>';
    return dock('zoom', full ? I.fit : I.fill, full ? tx('الصورة كاملة') : tx('ملء الشاشة'));
  };
  S.toggleZoom = function (to) {
    if (!Player.setAspect) return;
    var full = Player.aspectKey() !== 'fit';
    if (to === undefined) to = full ? 'fit' : 'cover';
    if (to === Player.aspectKey()) return;
    Player.setAspect(to);
    UI.toast(to === 'fit' ? tx('الصورة كاملة') : tx('ملء الشاشة'), 1400);
    this.tpRender();
  };

  /* one press moves to the next picture mode (fit, fill, stretch, 16:9, 4:3, zoom, and round again);
     its name shows for a moment */
  S.cycleAspect = function () {
    if (!Player.cycleAspect) { this.aspectMenu(); return; }
    var name = Player.cycleAspect();
    UI.toast(name, 1200);
  };

  /* two fingers apart = fill the screen, together = the whole picture (like other video apps) */
  (function () {
    var d0 = 0;
    function dist(t) { var x = t[0].clientX - t[1].clientX, y = t[0].clientY - t[1].clientY; return Math.sqrt(x * x + y * y); }
    document.addEventListener('touchstart', function (e) {
      d0 = e.touches.length === 2 && App.current() === 'player' && !UI.modal() ? dist(e.touches) : 0;
    }, { passive: true });
    document.addEventListener('touchmove', function (e) {
      if (!d0 || e.touches.length !== 2) return;
      var r = dist(e.touches) / d0;
      if (r > 1.25) { d0 = 0; S.toggleZoom('cover'); }
      else if (r < 0.8) { d0 = 0; S.toggleZoom('fit'); }
    }, { passive: true });
    document.addEventListener('touchend', function () { d0 = 0; }, { passive: true });
  })();

  /* subtitles: the tracks, then how they look */
  S.subsMenu = function () {
    var self = this, tr = Player.getTracks('TEXT'), items = [];
    if (tr.length) {
      items.push({ label: tx('بدون ترجمة'), value: -1, selected: !Player.subtitlesOn() });
      for (var i = 0; i < tr.length; i++) items.push({ label: tr[i].label, value: tr[i].index, selected: tr[i].selected });
    } else items.push({ label: tx('لا توجد ترجمة منفصلة في هذا المحتوى'), sub: tx('إن ظهرت ترجمة فهي جزء من الصورة نفسها، ولا يمكن تغيير حجمها أو لونها'), value: '__none' });
    items.push({ label: tx('شكل الترجمة'), sub: SubStyle.summary(), value: '__style' });
    UI.menu({
      title: tx('الترجمة'), items: items,
      onSelect: function (v) {
        if (v === '__style') { setTimeout(function () { SubStyle.menu(function () { self.menuClosed(); }); }, 60); return; }
        if (v === -1) { Player.subtitlesOff(); self.subtitle(''); UI.toast(tx('تم إيقاف الترجمة')); }
        else if (v !== null && v !== '__none' && Player.selectTrack('TEXT', v)) UI.toast(tx('تم تفعيل الترجمة'));
        self.menuClosed();
      }
    });
  };

  /* ---------------- buttons ---------------- */
  S.tpAction = function (a) {
    var self = this;
    switch (a) {
      case 'back': this.exit(); return;
      case 'toggle':
        if (Player.state() === 'error') { this.p.startAt = this.time; this.start(); return; }
        Player.toggle(); this.showOSD(true); return;
      case 'rw10': this.seekBy(-10, true); return;
      case 'ff10': this.seekBy(10, true); return;
      case 'episodes': this.openEps(); return;
      case 'speed': this.hideOSD(); this.speedMenu(); return;
      case 'aspect': this.cycleAspect(); this.showOSD(); return;
      case 'audio': case 'subs': this.hideOSD(); this.barAction(a); return;
      case 'channels': this.openZap(); return;
      case 'zoom': this.toggleZoom(); this.showOSD(); return;
      case 'chPrev': this.zapTo(this.p.index - 1); return;
      case 'chNext': this.zapTo(this.p.index + 1); return;
      case 'prevEp': this.changeEpisode(-1); return;
      case 'nextEp': this.changeEpisode(1); return;
      case 'fav':
        var on = Store.toggleFav(this.channel());
        UI.toast(on ? tx('تمت إضافة القناة للمفضلة') : tx('تمت إزالة القناة من المفضلة'));
        this.tpRender(); this.showOSD();
        return;
    }
    setTimeout(function () { self.showOSD(); }, 0);
  };

  /* the timeline follows the finger; the film jumps when the finger lifts */
  function bindBar() {
    var at = function (e) {
      var bar = U.$('tp-bar'), d = Player.getDuration() || S.dur;
      if (!bar || !d) return null;
      var r = bar.getBoundingClientRect(), x = (e.touches && e.touches.length ? e.touches[0] : (e.changedTouches ? e.changedTouches[0] : e)).clientX;
      return U.clamp((x - r.left) / r.width, 0, 1) * d;
    };
    var down = false;
    function start(e) {
      if (!e.target || !e.target.closest || !e.target.closest('#tp-bar')) return;
      var t = at(e);
      if (t === null) return;
      down = true;
      if (S.seekTarget !== null) S.cancelSeek();
      S.tpDrag = t;
