      S.tpProgress();
      if (e.cancelable) e.preventDefault();
    }
    function end(e) {
      if (!down) return;
      down = false;
      U.removeClass(box, 'drag');
      var t = S.tpDrag;
      S.tpDrag = null;
      if (t !== null && t !== undefined) {
        Player.seekTo(t);
        S.time = t;
        S.updateProgress();
      }
      S.showOSD();
      if (e && e.cancelable) e.preventDefault();
    }
    box.addEventListener('touchstart', start, { passive: false });
    box.addEventListener('touchmove', move, { passive: false });
    box.addEventListener('touchend', end, { passive: false });
    box.addEventListener('touchcancel', end, { passive: false });
    box.addEventListener('mousedown', function (e) { start(e); if (down) { var mm = function (ev) { move(ev); }, mu = function (ev) { document.removeEventListener('mousemove', mm); document.removeEventListener('mouseup', mu); end(ev); }; document.addEventListener('mousemove', mm); document.addEventListener('mouseup', mu); } });
  }

  /* ---------------- hooks into the TV player ---------------- */
  var base = {
    renderBottom: S.renderBottom, updateProgress: S.updateProgress, showOSD: S.showOSD,
    hideOSD: S.hideOSD, hide: S.hide, center: S.center
