  S.updateProgress = function (at) {
    base.updateProgress.apply(this, arguments);
    if (touch()) this.tpProgress(at);
  };
  S.showOSD = function (sticky) {
    base.showOSD.apply(this, arguments);
    if (!touch() || !this.p) return;
    el();
    if (!box.innerHTML) this.tpRender();
    var c = U.$('tp-clock');
    if (c) c.innerHTML = UI.clockText();
    U.addClass(box, 'show');
    /* a film that is jumping keeps its controls up a little longer */
    if (!sticky && !this.paused && this.barIdx < 0 && this.seekTarget === null) {
      var self = this;
      clearTimeout(this.osdTimer);
      this.osdTimer = setTimeout(function () { if (!self.tpDrag) self.hideOSD(); }, 4500);
    }
  };
  S.hideOSD = function () {
    base.hideOSD.apply(this, arguments);
    if (box) U.removeClass(box, 'show');
  };
  S.hide = function () {
    if (box) { U.removeClass(box, 'show'); box.innerHTML = ''; }
    base.hide.apply(this, arguments);
  };
  /* the big pause sign in the middle is not needed: the play button is there */
  S.center = function (what) {
    if (touch() && what === 'pause') what = '';
    base.center.call(this, what);
  };
  var sub = S.subtitle;
  S.subtitle = function (text, ms) {
    sub.apply(this, arguments);
    var el = U.$('pl-sub');
    if (text && el) el.innerHTML = '<span>' + el.innerHTML + '</span>';
  };
  var show = S.show;
  S.show = function () { try { SubStyle.apply(); } catch (e) {} return show.apply(this, arguments); };

  /* on a touch screen a press of ±10 jumps almost at once (the remote waits longer to add up held keys) */
  var seekBy = S.seekBy;
