    var self = this;
    clearTimeout(this.seekTimer);
    this.seekTimer = setTimeout(function () { self.commitSeek(); }, 350);
  };

  /* a jump that has just happened: show the new place right away */
  var commit = S.commitSeek;
  S.commitSeek = function () { var r = commit.apply(this, arguments); if (touch()) this.tpProgress(); return r; };
})();

/* ==========================================================================
   Settings — one fixed list of sections; what is inside the chosen section is
   shown beside it at once (TV, tablet, car, Mac), ready to pick with one press:
   the languages, the video player's choices, the playlists ... No window opens
   over another to change a setting, and a choice is saved the moment it is made.
   On a phone the list fills the screen and a section opens on its own page.

   Remote / keys: up and down walk the list and the section beside it follows;
   the arrow toward the section (or OK) goes into it; the arrow back, or Back,
   returns to the list.
   ========================================================================== */
Screens.settings = {
  sec: 0,          /* the section shown */
  pane: 'menu',    /* where the highlight is: 'menu' or 'content' */
  r: 0, c: 0,      /* the highlighted control inside the section (row, place in the row) */
  open: false,     /* phone: a section is open on its own page */
  grid: [],        /* the section's controls, row by row: [[{act, hold}]] */

  wide: function () { return !!(window.Device && Device.touch() && !Device.phone() && Device.landscape()); },

  sections: function () {
    var s = Store.getSettings(), act = Store.activePlaylist(), sub = SubStyle.current();
    var sortName = s.sort === 'server' ? tx('كما في السيرفر') : (s.sortDir === 'old' ? tx('الأقدم أولاً') : tx('الأحدث أولاً'));
    return [
      { id: 'lists', name: tx('قوائم التشغيل'), icon: T.ICON.list, value: (act && act.name) || '' },
      { id: 'player', name: tx('مشغل الفيديو'), icon: T.ICON.play,
        value: Player.engineName() + ' · ' + (s.liveFormat === 'm3u8' ? 'HLS' : 'TS') },
      { id: 'screen', name: tx('الشاشة والترجمة'), icon: T.ICON.screen,
        value: (Player.aspectName ? Player.aspectName() : '') + ' · ' + tx('ترجمة') + ' ' + sub.size.name },
      { id: 'lang', name: tx('اللغة'), icon: T.ICON.globe, value: I18N.name() },
      { id: 'sort', name: tx('الترتيب والساعة'), icon: T.ICON.sortNew,
        value: sortName + ' · ' + (s.clock24 ? '24 ' + tx('ساعة') : '12 ' + tx('ساعة')) },
      { id: 'lock', name: tx('حماية الأطفال'), icon: T.ICON.lock, value: Parental.has() ? tx('مفعّلة') : tx('غير مفعّلة') },
      { id: 'updates', name: tx('التحديثات'), icon: T.ICON.restart, value: OTA.summary() },
      { id: 'logout', name: tx('تسجيل الخروج'), icon: T.ICON.logout, value: '', danger: true }
    ];
  },

  show: function () {
    this.sec = 0; this.pane = 'menu'; this.r = 0; this.c = 0; this.open = false;
    this.draw();
  },

  resume: function (result) {
    var self = this;
    this.draw();
    /* back from adding a playlist: name it (unless a name was typed) */
    if (result && result.added && !result.named) {
      var list = Store.getPlaylists();
      for (var i = 0; i < list.length; i++) {
        if (list[i].id === result.added) {
          var p = list[i];
          setTimeout(function () { if (App.current() === 'settings') self.rename(p, true); }, 350);
        }
      }
    }
  },

  /* a section chosen in the list (a tap, or the highlight moving onto it) */
  pickSec: function (i, tapped) {
    var n = this.sections().length;
    this.sec = Math.max(0, Math.min(n - 1, i));
    this.r = 0; this.c = 0;
    if (!this.wide() && tapped) { this.open = true; this.pane = 'content'; }
    else this.pane = 'menu';
    this.draw();
    var pane = U.$('set-list');
    if (pane) pane.scrollTop = 0;
  },

  /* ---------------- drawing ---------------- */
  draw: function () {
    var wide = this.wide(), secs = this.sections(), cur = secs[this.sec] || secs[0];
    var showMenu = wide || !this.open, showPane = wide || this.open;
    var mh = '';
    for (var i = 0; i < secs.length; i++) {
      var x = secs[i];
      mh += '<button type="button" class="set-mi' + (i === this.sec && wide ? ' on' : '') + (x.danger ? ' out' : '') +
        (i === this.sec && this.pane === 'menu' ? ' focused' : '') + '" data-sec="' + i + '">' +
        '<span class="set-ic">' + x.icon + '</span><span class="set-mt"><b>' + U.esc(x.name) + '</b>' +
        (x.value ? '<small>' + U.esc(x.value) + '</small>' : '') + '</span>' +
        (!wide && !x.danger ? '<span class="set-chev">' + T.ICON.back + '</span>' : '') + '</button>';
    }
    var menu = U.$('set-groups'), pane = U.$('set-list'), acc = U.$('set-account');
    menu.innerHTML = mh;
    menu.style.display = showMenu ? '' : 'none';
    if (acc) acc.style.display = 'none';
    var h1 = document.querySelector('#scr-settings .tb-title h1');
    if (h1) h1.textContent = !wide && this.open ? cur.name : tx('الإعدادات');
    if (!showPane) { pane.style.display = 'none'; pane.innerHTML = ''; this.grid = []; return; }
    pane.style.display = '';
    this.render(this.content(cur.id));
  },

  /* a section's content: { title, lead, blocks: [...] } -> the page and the grid of controls */
  render: function (spec) {
    var self = this, grid = [], h = '';
    if (spec.title && this.wide()) h += '<h2 class="sp-title">' + U.esc(spec.title) + '</h2>';
    if (spec.lead) h += '<p class="sp-lead">' + U.esc(spec.lead) + '</p>';
    function item(it, cls, inner) {
      var r = grid.length - 1, c = grid[r].length;
      grid[r].push(it);
      var f = self.pane === 'content' && r === self.r && c === self.c;
      return '<button type="button" class="' + cls + (it.on ? ' on' : '') + (f ? ' focused' : '') + '" data-r="' + r + '" data-c="' + c + '">' + inner + '</button>';
    }
