    for (var t = 0; t < order.length; t++) {
      var kk = order[t], ls = this.res[kk];
      if (ls === null) { waiting = true; continue; }
      if (!ls || !ls.length) continue;
      any = true;
      h += '<section class="th-sec"><div class="th-sec-head"><h2>' + NAMES[kk] + ' <span class="muted">' + ls.length + (ls.length >= MAX ? '+' : '') + '</span></h2>' +
        (ls.length > (kk === 'live' ? 5 : 12) ? '<button type="button" class="t-link" data-act="more" data-k="' + kk + '">' + tx('عرض الكل') + '</button>' : '') + '</div>';
      h += '<div class="' + (kk === 'live' ? 'ts-list' : 'th-row r-poster') + '">';
      /* everything at once: a few channels, then the films and series as posters */
      for (i = 0; i < ls.length && i < (kk === 'live' ? 5 : 12); i++) h += this.card(kk, ls[i], i);
      h += '</div></section>';
    }
    if (waiting) h += '<div class="t-state inline"><div class="t-spin"></div></div>';
    else if (!any) h = '<p class="t-empty-s">' + tx('لا توجد نتائج لـ') + ' «' + T.esc(this.q) + '».</p>';
    box.innerHTML = h;
  };

  /* more results as the list nears its end (drawing hundreds of posters at once made typing heavy) */
  S.more = function () {
    var k = this.type, list = this.res[k], grid = U.$('ts-items'), box = U.$('ts-res');
    if (k === 'all' || !list || !grid || this.shown >= list.length) return;
    if (box.scrollTop + box.clientHeight < box.scrollHeight - 600) return;
    var h = '', end = Math.min(list.length, this.shown + CHUNK);
    for (var i = this.shown; i < end; i++) h += this.card(k, list[i], i);
    this.shown = end;
    grid.insertAdjacentHTML('beforeend', h);
  };

  S.open = function (k, i) {
    if (k === 'saga') { if (this.sagaHits && this.sagaHits[i]) App.go('saga', { saga: this.sagaHits[i] }); return; }
    var list = this.res[k];
    if (!list || !list[i]) return;
    if (k === 'live') App.go('player', { kind: 'live', list: list, index: i, catName: tx('نتائج البحث') });
    else if (k === 'vod') App.go('movie', { item: list[i] });
    else App.go('series', { item: list[i] });
  };

  S.onKey = function (k) { if (k === 'back') App.back(); };
})();

