      });
    });
  }

  function readyNotes() {
    try { return JSON.parse(ls('ota.readyNotes') || '[]'); } catch (e) { return []; }
  }

  function autoCheck() {
    if (!auto()) return;
    check(function (r) {
      if (r.status === 'ready' && r.fresh && window.UI) {
        UI.toast(tx('تحديث جديد') + ' (' + r.version + ') ' + tx('جاهز — يعمل عند فتح التطبيق في المرة القادمة'), 6000);
      }
    });
  }

  /* called as soon as the app has started: this version works */
  function start() {
    ls('ota.trying', null);
    setTimeout(autoCheck, FIRST_CHECK);
    setInterval(autoCheck, EVERY);
  }

  function restart() {
    try { if (window.Player && Player.stop) Player.stop(); } catch (e) {}
    location.reload();
  }

  /* forget every downloaded version: the code inside the package runs again */
  function reset() {
    /* and do not download this same version again (a newer one is fine) */
    var v = BOOT.from === 'update' ? BOOT.running : ls('ota.ready');
    if (v) ls('ota.bad', v);
    ls('ota.bundle', null); ls('ota.ready', null); ls('ota.readyNotes', null); ls('ota.trying', null);
    restart();
  }

  /* ---------------- the "updates" item in the settings ---------------- */
  function summary() {
    var v = tx('الإصدار') + ' ' + BOOT.running;
    if (ready()) return v + ' · ' + tx('تحديث') + ' ' + ready() + ' ' + tx('جاهز');
    if (st.status === 'needShell') return v + ' · ' + tx('تحديث كبير متاح');
    return v;
  }
  function hint() {
    if (!auto()) return tx('التحديث التلقائي متوقف — اضغط للبحث عن تحديث');
    return tx('يبحث عن التحديثات تلقائياً كل 6 ساعات وينزّلها');
  }
  function notesText(n) { return n && n.length ? '• ' + n.join('\n• ') : ''; }

  function offerRestart(v, notes, onDone) {
    UI.confirm({
      title: tx('التحديث') + ' ' + v + ' ' + tx('جاهز'), text: notesText(notes) || tx('يعمل بعد إعادة تشغيل التطبيق.'),
      buttons: [{ label: tx('إعادة تشغيل التطبيق الآن'), value: 'now' }, { label: tx('لاحقاً'), value: 'later' }],
      onSelect: function (x) { if (x === 'now') restart(); else if (onDone) onDone(); }
    });
  }

  function checkNow(onDone) {
    UI.loading(true, tx('جارٍ البحث عن تحديث...'));
    check(function (r) {
      UI.loading(false);
      if (r.status === 'ready') { offerRestart(r.version, r.notes, onDone); return; }
      if (r.status === 'latest') UI.toast(tx('لديك أحدث إصدار') + ' (' + BOOT.running + ')');
      else if (r.status === 'needShell') {
        UI.confirm({
          title: tx('تحديث كبير متاح') + ' (' + r.version + ')',
          text: tx('يحتاج هذا التحديث إلى تثبيته مرة واحدة من الكمبيوتر، ثم تعود التحديثات للنزول تلقائياً.'),
          buttons: [{ label: tx('حسناً'), value: 'ok' }], onSelect: function () { if (onDone) onDone(); }
        });
        return;
      }
      else if (r.status === 'busy') UI.toast(tx('البحث عن تحديث جارٍ بالفعل...'));
      else UI.toast(tx('تعذّر الوصول إلى سيرفر التحديثات — تأكد من الإنترنت'));
      if (onDone) onDone();
    });
  }

  function menu(onDone) {
    var items = [];
    if (ready()) items.push({ label: tx('تشغيل التحديث') + ' ' + ready() + ' ' + tx('الآن'), value: 'apply' });
    items.push({ label: tx('البحث عن تحديث الآن'), value: 'check' });
    items.push({ label: tx('التحديث التلقائي:') + ' ' + (auto() ? tx('مفعّل') : tx('متوقف')), value: 'auto',
      sub: auto() ? tx('اضغط للإيقاف') : tx('اضغط للتفعيل') });
    if (BOOT.notes && BOOT.notes.length) items.push({ label: tx('ما الجديد في الإصدار') + ' ' + BOOT.running, value: 'notes' });
    if (BOOT.from === 'update') items.push({ label: tx('الرجوع للنسخة الأصلية') + ' (' + BOOT.base + ')', value: 'reset',
      sub: tx('إذا واجهت مشكلة في التحديث') });
    UI.menu({
      title: tx('التحديثات · الإصدار') + ' ' + BOOT.running, items: items,
      onSelect: function (v) {
        if (v === 'apply') restart();
        else if (v === 'check') checkNow(onDone);
        else if (v === 'auto') { setAuto(!auto()); UI.toast(auto() ? tx('التحديث التلقائي مفعّل') : tx('التحديث التلقائي متوقف')); if (onDone) onDone(); }
        else if (v === 'notes') {
          UI.confirm({ title: tx('الجديد في الإصدار') + ' ' + BOOT.running, text: notesText(BOOT.notes),
            buttons: [{ label: tx('حسناً'), value: 'ok' }], onSelect: function () { if (onDone) onDone(); } });
        }
        else if (v === 'reset') {
          UI.confirm({
            title: tx('الرجوع للنسخة الأصلية؟'), text: txe('سيُزال التحديث ' + BOOT.running + ' ويعود الإصدار ' + BOOT.base + '. بياناتك ومفضلتك لن تتأثر.', 'Update ' + BOOT.running + ' will be removed and version ' + BOOT.base + ' comes back. Your data and Favourites stay as they are.'),
            buttons: [{ label: tx('رجوع'), value: 'yes', danger: true }, { label: tx('إلغاء'), value: 'no' }], index: 1,
            onSelect: function (x) { if (x === 'yes') reset(); else if (onDone) onDone(); }
