})();

/* ==========================================================================
   app.js — starts the app, switches screens and routes remote-control keys
   ========================================================================== */
var App = (function () {
  var stack = [];          /* history: [{name, params}] */
  var current = null;
  var currentName = '';

  /* on a phone / tablet some screens have their own finger version (t_home, t_browse ...) */
  function route(name) {
    return (window.Device && Device.touch() && Screens['t_' + name]) ? 't_' + name : name;
  }

  function activate(name, params, returning, result) {
    name = route(name);
    var all = document.querySelectorAll('.screen');
    for (var i = 0; i < all.length; i++) all[i].style.display = 'none';
    current = Screens[name];
    currentName = name;
    current.el = U.$('scr-' + name);
    current.el.style.display = 'block';
    /* phones and tablets: the new screen fades in softly (opacity and movement only: cheap to draw) */
    if (window.Device && Device.touch() && name !== 'player') {
      var sel = current.el;
      U.removeClass(sel, returning ? 't-in' : 't-back');
      U.removeClass(sel, returning ? 't-back' : 't-in');
      void sel.offsetWidth;
      U.addClass(sel, returning ? 't-back' : 't-in');
    }
    U.toggleClass(document.body, 'playing', name === 'player');
    U.toggleClass(document.documentElement, 'deep', stack.length > 1);
    /* phones and tablets: a video plays sideways, everything else follows the device */
    if (window.Device && Device.touch()) Device.orientation(name === 'player' ? 'landscape' : 'any');
    fitScreen();
    if (returning && current.resume) current.resume(result);
    else current.show(params || {});
    if (window.TvNav) TvNav.screen(returning);
    UI.tickClock();
  }

  /* opts: {reset:true} clears history, {replace:true} replaces the current screen */
  function go(name, params, opts) {
    if (current && current.hide) current.hide();
    if (opts && opts.reset) stack = [];
    else if (opts && opts.replace) stack.pop();
    stack.push({ name: name, params: params || {} });
    activate(name, params, false);
  }

  function back(result) {
    if (stack.length <= 1) { exitConfirm(); return; }
    if (current && current.hide) current.hide();
    stack.pop();
    var prev = stack[stack.length - 1];
    activate(prev.name, prev.params, true, result);
  }

  function exitConfirm() {
    UI.confirm({
      title: tx('الخروج من التطبيق؟'),
      buttons: [{ label: tx('خروج'), value: 'exit', danger: true }, { label: tx('إلغاء'), value: 'no' }],
      index: 1,
      onSelect: function (v) { if (v === 'exit') exitApp(); }
    });
  }

  function exitApp() {
    Player.stop();
    try { tizen.application.getCurrentApplication().exit(); }
    catch (e) { UI.toast(tx('تعذّر الخروج')); }
  }

  /* ---------------- keys ---------------- */
  /* holding OK: a screen that wants it (current.wantsHold) gets 'hold'
     after HOLD_MS, a short press still gets 'enter' when OK is let go */
  var HOLD_MS = 650;
  var hold = null, okDown = false, keyupSeen = false;

  function fireHold() {
    if (!hold || hold.done) return;
    hold.done = true;
    clearTimeout(hold.timer);
    dispatch('hold', null);
  }

  function holdKeyDown(e) {
    if (hold) {                                  /* the remote repeats OK while it is held */
      if (U.now() - hold.t0 >= HOLD_MS) fireHold();
      return;
    }
    if (e.repeat || (okDown && keyupSeen)) return;   /* still held from before (another screen or zone) */
    okDown = true;
    hold = { t0: U.now(), done: false };
    hold.timer = setTimeout(function () {
      if (!hold || hold.done) return;
      if (keyupSeen) { fireHold(); return; }
      /* this device never sent a key-up yet: cannot tell a hold, so it is a normal press */
      hold = null; okDown = false;
      dispatch('enter', null);
    }, HOLD_MS);
  }

  function onKeyUp(e) {
    keyupSeen = true;
    if (e.keyCode !== 13) return;
    okDown = false;
    if (!hold) return;
    var h = hold;
    hold = null;
    clearTimeout(h.timer);
    if (!h.done) dispatch('enter', e);           /* let go before HOLD_MS: a normal press */
  }

  function onKeyDown(e) {
    var c = e.keyCode;
    var k = Keys.name(e);
    var ae = document.activeElement;
    var inInput = ae && ae.tagName === 'INPUT';

    if (inInput) {
      /* typing in a text box: only intercept "done", "cancel" and up/down */
