    unlisten(g);
    if (e.touches.length !== 1) { g = null; return; }
    /* the phone / tablet screens (t_...) scroll by themselves and handle their own presses: nothing to
       do here, and listening to the finger's moves would make every scroll wait for the page */
    if (/^t_/.test(screenName()) && !(UI.modal && UI.modal())) { g = null; return; }
    var p = e.touches[0], t = e.target;
    if (closest(t, '#tpad') || closest(t, '#tpad-btn')) { g = null; return; }
