    var scrollEl = !native && !list && screenName() === 'settings' && !UI.modal() ? closest(t, '#set-list') : null;
    if (!native && !list && !scrollEl && screenName() === 'playlists' && !UI.modal()) scrollEl = closest(t, '#pls-list');
